enum SerialDeferredSafetyRegistration : std::uint32_t
{
    SerialReturnsPending = 1u << 0,
    SerialWalFailureBlocksCommit = 1u << 1,
    SerialFlushConverges = 1u << 2,
    SerialBusyWalProgress = 1u << 3,
    SerialUnsafeProofFallsBack = 1u << 4,
    SerialShutdownConverges = 1u << 5,
    SerialPreDurableKillIsTruthful = 1u << 6,
    SerialIdleFollowerHonorsDurability = 1u << 7,
    SerialWriterOpenRevalidatesQuiescence = 1u << 8,
    SerialCloseStatusIsTruthful = 1u << 9,
};

constexpr std::uint32_t kAllSerialDeferredSafetyRegistrations =
    SerialReturnsPending |
    SerialWalFailureBlocksCommit |
    SerialFlushConverges |
    SerialBusyWalProgress |
    SerialUnsafeProofFallsBack |
    SerialShutdownConverges |
    SerialPreDurableKillIsTruthful |
    SerialIdleFollowerHonorsDurability |
    SerialWriterOpenRevalidatesQuiescence |
    SerialCloseStatusIsTruthful;

std::atomic<std::uint32_t> g_serial_deferred_safety_registrations{0};
std::atomic<FSP_FILE_SYSTEM*> g_shutdown_dispatcher_stopped_fs{nullptr};
MountContext* g_shutdown_order_context = nullptr;
std::atomic<bool> g_shutdown_durable_before_dispatcher_stop{false};
std::atomic<bool> g_shutdown_dispatcher_release{false};
std::atomic<bool> g_shutdown_mount_removed{false};
std::atomic<bool> g_shutdown_remove_release{false};
std::atomic<bool> g_shutdown_remove_entered{false};
std::atomic<bool> g_shutdown_remove_exited{false};
std::atomic<bool> g_shutdown_delete_release{false};
std::atomic<int> g_shutdown_teardown_sequence{0};
std::atomic<int> g_shutdown_stop_return_order{0};
std::atomic<int> g_shutdown_remove_order{0};
std::atomic<int> g_shutdown_delete_order{0};
