MountContext* g_shutdown_terminal_status_context = nullptr;
std::atomic<bool> g_shutdown_terminal_status_not_ready_at_stop{false};
std::atomic<std::uint32_t> g_shutdown_terminal_active_callbacks_at_stop{0};

std::vector<ActiveWinFspDriverProbeResult> g_winfsp_probe_results;
std::size_t g_winfsp_probe_index = 0;
std::uint32_t g_winfsp_start_calls = 0;
NTSTATUS g_winfsp_start_status = STATUS_SUCCESS;

ActiveWinFspDriverProbeResult ProbeWinFspDriverForStartupTest(
    std::uint16_t& major,
    std::uint16_t& minor,
    std::uint16_t& build,
    std::uint16_t& revision,
    std::filesystem::path& binary_path,
    const std::filesystem::path& expected_binary_path)
{
    if (g_winfsp_probe_index >= g_winfsp_probe_results.size())
    {
        return ActiveWinFspDriverProbeResult::NotFound;
    }

    const auto result = g_winfsp_probe_results[g_winfsp_probe_index++];
    if (result == ActiveWinFspDriverProbeResult::Found)
    {
        major = 2;
        minor = 2;
        build = 26215;
        revision = 0;
        binary_path = expected_binary_path;
    }
    return result;
}

NTSTATUS StartWinFspServiceForStartupTest()
{
    ++g_winfsp_start_calls;
    return g_winfsp_start_status;
}

