void StopDispatcherForShutdownTest(FSP_FILE_SYSTEM* fs)
{
    if (g_shutdown_order_context && g_shutdown_order_context->tx_manager)
    {
        const auto watermarks = g_shutdown_order_context->tx_manager->Watermarks();
        g_shutdown_durable_before_dispatcher_stop.store(
            watermarks.accepted_sequence != 0 &&
                watermarks.accepted_sequence == watermarks.apfs_durable_sequence &&
                watermarks.accepted_sequence == watermarks.cleanup_sequence,
            std::memory_order_release);
    }
    g_shutdown_dispatcher_stopped_fs.store(fs, std::memory_order_release);
}

void StopDispatcherAndInspectTerminalStatusForShutdownTest(FSP_FILE_SYSTEM* fs)
{
    std::ifstream status_in(g_shutdown_terminal_status_path, std::ios::binary);
    const std::string status_json{
        std::istreambuf_iterator<char>(status_in),
        std::istreambuf_iterator<char>()};
    g_shutdown_terminal_status_not_ready_at_stop.store(
        status_json.find("\"mountReady\":false") != std::string::npos,
        std::memory_order_release);
    g_shutdown_terminal_active_callbacks_at_stop.store(
        g_shutdown_terminal_status_context
            ? g_shutdown_terminal_status_context->active_callback_count.load(std::memory_order_acquire)
            : 0,
        std::memory_order_release);
    StopDispatcherForShutdownTest(fs);
}

void StopDispatcherUntilMountRemovedForShutdownTest(FSP_FILE_SYSTEM* fs)
{
    g_shutdown_dispatcher_stopped_fs.store(fs, std::memory_order_release);
    while (!g_shutdown_dispatcher_release.load(std::memory_order_acquire))
    {
        Sleep(1);
    }
}

