bool TestRecursiveReindexReusesNormalizedChildPaths()
{
    MountContext context{};
    context.overlay_write_enabled = true;
    SeedRoot(context);

    auto root = context.nodes.at(Key(L"\\"));
    AddChildName(*root, L"srcdir");

    auto srcdir = MakeNode(L"\\srcdir", true, false);
    AddChildName(*srcdir, L"subdir");
    context.nodes.emplace(Key(srcdir->path), srcdir);

    auto subdir = MakeNode(L"\\srcdir\\subdir", true, false);
    AddChildName(*subdir, L"leafdir");
    context.nodes.emplace(Key(subdir->path), subdir);

    auto leafdir = MakeNode(L"\\srcdir\\subdir\\leafdir", true, false);
    context.nodes.emplace(Key(leafdir->path), leafdir);

    ResetChildNameDebugCountersForTest();
    const auto before = g_normalize_path_call_count_for_test;
    const auto reindexed = ReindexNodePathsLocked(&context, srcdir, L"\\srcdir", L"\\moved");
    const auto after = g_normalize_path_call_count_for_test;
    if (!Require(reindexed, "Recursive reindex should succeed for a directory-only subtree"))
    {
        return false;
    }

    if (!Require(
            context.nodes.find(Key(L"\\srcdir")) == context.nodes.end() &&
            context.nodes.find(Key(L"\\srcdir\\subdir")) == context.nodes.end() &&
            context.nodes.find(Key(L"\\srcdir\\subdir\\leafdir")) == context.nodes.end(),
            "Recursive reindex should remove old subtree keys"))
    {
        return false;
    }
    if (!Require(
            context.nodes.find(Key(L"\\moved")) != context.nodes.end() &&
            context.nodes.find(Key(L"\\moved\\subdir")) != context.nodes.end() &&
            context.nodes.find(Key(L"\\moved\\subdir\\leafdir")) != context.nodes.end(),
            "Recursive reindex should add new subtree keys"))
    {
        return false;
    }

    constexpr std::uint64_t expected_key_and_set_path_normalizations = 9;
    return Require(
               after - before <= expected_key_and_set_path_normalizations,
               "Recursive reindex child descent should reuse normalized child paths") &&
           Require(
               DebugChildNodeCachedLookupCountForTest() == 2,
               "Recursive reindex should find descendants through cached parent path keys") &&
           Require(
               DebugChildNodeCachedLookupFallbackCountForTest() == 0,
               "Recursive reindex should not fall back when old subtree keys are current");
}

bool TestCreateReusesNormalizedParentPath()
{
#ifdef APFSACCESS_FSHOST_UNIT_TEST
    MountContext context{};
    context.overlay_write_enabled = true;
    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);

    auto root = context.nodes.at(Key(L"\\"));
    AddChildName(*root, L"parent");
    auto parent = MakeNode(L"\\parent", true, false);
    context.nodes.emplace(Key(parent->path), parent);

    auto fs = BuildFileSystem(&context);
    PVOID out_ctx = nullptr;
    FSP_FSCTL_FILE_INFO info{};
    ResetChildNameDebugCountersForTest();
    const auto before = g_normalize_path_call_count_for_test;
    const auto status = CB_Create(
        &fs,
        const_cast<PWSTR>(L"\\parent\\child"),
        FILE_DIRECTORY_FILE,
        FILE_WRITE_DATA,
        0,
        nullptr,
        0,
        &out_ctx,
        &info);
    const auto after = g_normalize_path_call_count_for_test;

    if (!Require(status == STATUS_SUCCESS && out_ctx != nullptr, "Directory create should succeed under an already-loaded parent"))
    {
        if (out_ctx)
        {
            CB_Close(&fs, out_ctx);
        }
        return false;
    }
    CB_Close(&fs, out_ctx);

    if (!Require(context.nodes.find(Key(L"\\parent\\child")) != context.nodes.end(), "Directory create should add the child node"))
    {
        return false;
    }

    constexpr std::uint64_t expected_create_path_normalizations = 4;
    return Require(
               after - before <= expected_create_path_normalizations,
               "Create should reuse normalized parent and child paths through the hot lookup path") &&
           Require(
               DebugCreateParentReuseCountForTest() == 1,
               "Create should reuse the parent node loaded by the parent-directory check");
#else
    return true;
#endif
}

