bool TestDeferredCommitBarrierWaitsForInFlightWorker()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        context.deferred_commit_in_flight = true;
        context.deferred_commit_in_flight_target = 3;
        context.deferred_commit_requested = true;
        context.deferred_commit_requested_target = 9;
    }

    auto waiter = std::async(std::launch::async, [&context]()
    {
        return BeginDeferredCommitBarrier(&context, false);
    });
    const bool blocked_while_in_flight =
        waiter.wait_for(std::chrono::milliseconds(150)) != std::future_status::ready;

    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        context.deferred_commit_in_flight = false;
        context.deferred_commit_in_flight_target = 0;
    }
    context.deferred_commit_cv.notify_all();

    const bool barrier_started = waiter.get();
    bool queued_target_claimed = false;
    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        queued_target_claimed = context.deferred_commit_in_flight &&
            context.deferred_commit_in_flight_target == 9 &&
            !context.deferred_commit_requested;
        context.deferred_commit_in_flight = false;
        context.deferred_commit_in_flight_target = 0;
    }

    return Require(blocked_while_in_flight, "A direct barrier should wait for the in-flight deferred worker") &&
           Require(barrier_started, "A direct barrier should start after the worker completes") &&
           Require(queued_target_claimed, "A direct barrier should claim work queued behind the worker");
#else
    return true;
#endif
}

bool TestDeferredWorkerDoesNotPublishInFlightBeforeMutationQueueOwnership()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    ScopeExit clear_writeback_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
    }};

    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.native_write_enabled = true;
    context.test_force_native_mutation_staging_success = true;
    context.test_forced_native_commit_status =
        apfsaccess::rw::MetadataStore::CommitStatus::Committed;

    std::unique_lock<std::mutex> foreground_mutation_lock(context.mutation_callback_mutex);
    StartDeferredCommitWorker(&context);
    ScopeExit stop_worker{[&]()
    {
        if (foreground_mutation_lock.owns_lock())
        {
            foreground_mutation_lock.unlock();
        }
        CompleteDeferredCommitBarrier(&context, true, STATUS_SUCCESS);
        StopDeferredCommitWorker(&context);
    }};

    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        context.deferred_commit_requested = true;
        context.deferred_commit_requested_target = 0;
        context.deferred_commit_force_now = true;
        context.deferred_commit_first_request_tick_ms = static_cast<std::uint64_t>(GetTickCount64());
        context.deferred_commit_deadline = std::chrono::steady_clock::now();
        context.deferred_commit_deadline_tick_ms = context.deferred_commit_first_request_tick_ms;
    }
    context.deferred_commit_cv.notify_one();

    const auto claim_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while (context.deferred_commit_worker_claim_attempt_count.load(std::memory_order_acquire) == 0 &&
           std::chrono::steady_clock::now() < claim_deadline)
    {
        std::this_thread::yield();
    }

    const auto contention_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while (context.deferred_commit_worker_mutex_contention_count.load(std::memory_order_acquire) == 0 &&
           std::chrono::steady_clock::now() < contention_deadline)
    {
        std::this_thread::yield();
    }
    const bool worker_backed_off_from_mutation_queue =
        context.deferred_commit_worker_mutex_contention_count.load(std::memory_order_acquire) != 0;

    auto foreground_barrier = std::async(std::launch::async, [&]()
    {
        return BeginDeferredCommitBarrier(&context, false);
    });
    const auto barrier_ready_while_foreground_owns_queue =
        foreground_barrier.wait_for(std::chrono::milliseconds(250)) == std::future_status::ready;
    foreground_mutation_lock.unlock();
    const auto barrier_started = foreground_barrier.get();
    CompleteDeferredCommitBarrier(&context, true, STATUS_SUCCESS);

    return Require(
               context.deferred_commit_worker_claim_attempt_count.load(std::memory_order_acquire) != 0,
               "Deferred worker should reach the mutation-queue claim point") &&
           Require(
               barrier_ready_while_foreground_owns_queue,
               "A foreground barrier holding the mutation queue must not wait on a worker that is waiting for that queue") &&
           Require(
               worker_backed_off_from_mutation_queue,
               "Deferred worker must retry instead of blocking on the mutation queue") &&
           Require(barrier_started, "Foreground barrier should claim the queued deferred request");
#else
    return true;
#endif
}

bool TestDeferredCommitBarrierPropagatesWorkerFailure()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        context.deferred_commit_in_flight = true;
        context.deferred_commit_in_flight_target = 13;
        context.deferred_commit_last_status = STATUS_SUCCESS;
    }

    auto waiter = std::async(std::launch::async, [&context]()
    {
        return BeginDeferredCommitBarrier(&context, false);
    });
    const bool blocked_while_in_flight =
        waiter.wait_for(std::chrono::milliseconds(150)) != std::future_status::ready;
    CompleteDeferredCommitBarrier(&context, false, STATUS_IO_DEVICE_ERROR);
    const bool barrier_started = waiter.get();

    return Require(blocked_while_in_flight, "A direct barrier should wait for the failing worker") &&
           Require(!barrier_started, "A direct barrier should surface the worker failure") &&
           Require(context.deferred_commit_failed_target == 13, "A failed worker should publish its accepted target") &&
           Require(context.deferred_commit_last_status == STATUS_IO_DEVICE_ERROR, "A failed worker should preserve its failure status");
#else
    return true;
#endif
}

bool TestDeferredCommitBarrierRejectsEarlierFailedTargetAfterLaterCompletion()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        context.deferred_commit_in_flight = true;
        context.deferred_commit_in_flight_target = 5;
        context.deferred_commit_last_status = STATUS_SUCCESS;
    }
    CompleteDeferredCommitBarrier(&context, false, STATUS_IO_DEVICE_ERROR);

    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        context.deferred_commit_in_flight = true;
        context.deferred_commit_in_flight_target = 10;
        context.deferred_commit_last_status = STATUS_SUCCESS;
    }
    CompleteDeferredCommitBarrier(&context, false, STATUS_IO_DEVICE_ERROR);

    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        context.deferred_commit_completed_target = 12;
        context.deferred_commit_last_status = STATUS_SUCCESS;
    }

    const auto barrier_started = BeginDeferredCommitBarrier(&context, false, 7);
    return Require(
               !barrier_started,
               "A later completed target must not satisfy a barrier after an earlier target failed") &&
           Require(
               context.deferred_commit_failed_target == 5,
               "Ordered barrier failure evidence must retain the earliest failed target");
#else
    return true;
#endif
}

bool TestConcurrentDeferredCommitBarriersShareOrderedCompletion()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        context.deferred_commit_in_flight = true;
        context.deferred_commit_in_flight_target = 3;
        context.deferred_commit_requested = true;
        context.deferred_commit_requested_target = 9;
        context.deferred_commit_last_status = STATUS_SUCCESS;
    }

    auto first = std::async(std::launch::async, [&context]()
    {
        return BeginDeferredCommitBarrier(&context, false, 9);
    });
    auto second = std::async(std::launch::async, [&context]()
    {
        return BeginDeferredCommitBarrier(&context, false, 9);
    });
    const bool both_waited_for_first_target =
        first.wait_for(std::chrono::milliseconds(150)) != std::future_status::ready &&
        second.wait_for(std::chrono::milliseconds(0)) != std::future_status::ready;

    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        context.deferred_commit_in_flight = false;
        context.deferred_commit_in_flight_target = 0;
        context.deferred_commit_completed_target = 3;
    }
    context.deferred_commit_cv.notify_all();

    const auto claim_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while (first.wait_for(std::chrono::milliseconds(0)) != std::future_status::ready &&
           second.wait_for(std::chrono::milliseconds(0)) != std::future_status::ready &&
           std::chrono::steady_clock::now() < claim_deadline)
    {
        std::this_thread::yield();
    }

    bool one_waiter_claimed_target = false;
    bool queued_target_remains = false;
    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        one_waiter_claimed_target = context.deferred_commit_in_flight &&
            context.deferred_commit_in_flight_target == 9 &&
            !context.deferred_commit_requested;
        queued_target_remains = context.deferred_commit_requested;
        context.deferred_commit_in_flight = false;
        context.deferred_commit_in_flight_target = 0;
        context.deferred_commit_completed_target = 9;
    }
    context.deferred_commit_cv.notify_all();

    const auto first_result = first.get();
    const auto second_result = second.get();
    return Require(
               both_waited_for_first_target,
               "Concurrent barriers must wait for the already in-flight target") &&
           Require(
               one_waiter_claimed_target,
               "Only one concurrent barrier may claim the next ordered target") &&
           Require(
               !queued_target_remains,
               "The claimed target must be removed from the deferred request queue") &&
           Require(first_result && second_result, "Concurrent barriers must share ordered completion");
#else
    return true;
#endif
}

bool TestDeferredCommitBarrierWakesWhenWorkerStops()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        context.deferred_commit_in_flight = true;
        context.deferred_commit_in_flight_target = 17;
        context.deferred_commit_last_status = STATUS_SUCCESS;
    }

    auto waiter = std::async(std::launch::async, [&context]()
    {
        return BeginDeferredCommitBarrier(&context, false, 17);
    });
    const bool blocked_before_stop =
        waiter.wait_for(std::chrono::milliseconds(150)) != std::future_status::ready;

    StopDeferredCommitWorker(&context);
    const auto barrier_started = waiter.get();
    return Require(blocked_before_stop, "A barrier should wait while its worker target is in flight") &&
           Require(!barrier_started, "A stopping deferred worker must fail its waiting barriers") &&
           Require(
               context.deferred_commit_failed_target == 17,
               "Stopping a worker must retain the in-flight target as failed evidence");
#else
    return true;
#endif
}

bool TestFlushSurfacesPayloadFinalizationFailureImpl(bool volume_flush)
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"0");
    ScopeExit clear_defer_close_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
    }};

    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"flush-finalization-failure-" + std::to_wstring(GetTickCount64()));
    if (ec)
    {
        return Require(false, "Finalization failure test should resolve temp directory");
    }
    std::filesystem::create_directories(run_root, ec);
    if (ec)
    {
        return Require(false, "Finalization failure test should create temp directory");
    }

    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_recovery_policy = L"FailClosed";
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    context.test_force_native_mutation_staging_success = true;
    context.test_forced_native_commit_status =
        apfsaccess::rw::MetadataStore::CommitStatus::Committed;
    context.payload_spool_volume_identity = "flush-finalization-volume";
    context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{
            run_root / "spool",
            context.payload_spool_volume_identity,
            1024 * 1024,
            1024 * 1024,
            1024,
        });
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"DeferredContent");
    context.tx_manager->SetVolumeIdentity(L"flush-finalization-volume");
    context.tx_journal_file = run_root / "write-ahead.wal";
    context.tx_manager->SetJournalPath(context.tx_journal_file.wstring());

    const std::array<std::byte, 16> payload{
        std::byte{0x01}, std::byte{0x02}, std::byte{0x03}, std::byte{0x04},
        std::byte{0x05}, std::byte{0x06}, std::byte{0x07}, std::byte{0x08},
        std::byte{0x09}, std::byte{0x0a}, std::byte{0x0b}, std::byte{0x0c},
        std::byte{0x0d}, std::byte{0x0e}, std::byte{0x0f}, std::byte{0x10},
    };
    const apfsaccess::rw::MetadataStore::PayloadIdentity identity{8001, 3};
    if (!Require(
            RecordPayloadWriteMutationBestEffort(
                &context,
                L"\\flush-failure.bin",
                0,
                payload.data(),
                static_cast<std::uint32_t>(payload.size()),
                &identity),
            "Finalization failure test should stage a payload mutation"))
    {
        std::filesystem::remove_all(run_root, ec);
        return false;
    }

    const auto blocked_index_temp =
        context.payload_spool->SpoolFilePath().parent_path() / "payload-spool.idx.tmp";
    std::filesystem::create_directories(blocked_index_temp, ec);
    if (!Require(!ec, "Finalization failure test should block the spool index temp path"))
    {
        std::filesystem::remove_all(run_root, ec);
        return false;
    }
    ScopeExit cleanup{[&]()
    {
        std::filesystem::remove_all(blocked_index_temp, ec);
        if (context.payload_spool)
        {
            (void)context.payload_spool->FlushDirtyState();
            (void)context.payload_spool->CleanupThroughSequence(
                (std::numeric_limits<std::uint64_t>::max)());
        }
        std::filesystem::remove_all(run_root, ec);
    }};

    SeedRoot(context);
    auto file = MakeNode(L"\\flush-failure.bin", false, false);
    context.nodes.emplace(Key(file->path), file);
    OpenContext open_context{};
    open_context.node = file;
    auto fs = BuildFileSystem(&context);
    FSP_FSCTL_FILE_INFO info{};
    const auto status = CB_Flush(
        &fs,
        volume_flush ? nullptr : &open_context,
        volume_flush ? nullptr : &info);
    const auto spool_counters = context.payload_spool->SnapshotCounters();
    const auto journal_state = context.tx_manager->CurrentState();

    return Require(
               status == STATUS_UNSUCCESSFUL || status == STATUS_MEDIA_WRITE_PROTECTED,
               "Flush should surface payload finalization failure") &&
           Require(
               journal_state == apfsaccess::rw::TransactionManager::State::Idle,
               "Flush failure should abort the pending transaction journal") &&
           Require(
               spool_counters.cleanup_failures == 0,
               "A pre-cleanup finalization failure should not be reported as a cleanup failure");
#else
    return true;
#endif
}

bool TestFlushSurfacesPayloadFinalizationFailure()
{
    return TestFlushSurfacesPayloadFinalizationFailureImpl(false);
}

bool TestVolumeFlushSurfacesPayloadFinalizationFailure()
{
    return TestFlushSurfacesPayloadFinalizationFailureImpl(true);
}

bool TestReadOnlyCloseDoesNotRequeueDeferredCommit()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    ScopeExit clear_writeback_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
    }};

    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    context.pending_native_writes = true;
    context.test_force_native_mutation_staging_success = true;
    context.test_forced_native_mutation_count = 1;
    context.test_forced_native_mutations_content_only = true;
    SeedRoot(context);

    auto file = MakeNode(L"\\readonly-close.txt", false, false);
    file->open_handle_count = 1;
    context.nodes.emplace(Key(file->path), file);

    auto* read_context = new OpenContext();
    read_context->node = file;
    read_context->allow_read_data = true;

    auto fs = BuildFileSystem(&context);
    CB_Close(&fs, read_context);

    return Require(
        file->open_handle_count == 0 &&
            !context.close_commit_deferred.load(std::memory_order_acquire) &&
            context.deferred_close_commit_count.load(std::memory_order_acquire) == 0 &&
            context.test_native_commit_attempt_count == 0 &&
            context.last_foreground_mutation_tick_ms.load(std::memory_order_acquire) != 0,
        "Pure read closes should release accounting without requeueing pending native write-back");
#else
    return true;
#endif
}

bool TestNonDeleteCleanupDoesNotWaitForMutationQueue()
{
    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    SeedRoot(context);

    auto file = MakeNode(L"\\cleanup-fast.txt", false, false);
    file->open_handle_count = 1;
    context.nodes.emplace(Key(file->path), file);

    auto cleanup_context = std::make_unique<OpenContext>();
    cleanup_context->node = file;
    cleanup_context->allow_read_data = true;

    auto fs = BuildFileSystem(&context);
    std::unique_lock<std::mutex> mutation_lock(context.mutation_callback_mutex);
    auto cleanup_future = std::async(std::launch::async, [&]()
    {
        CB_Cleanup(&fs, cleanup_context.get(), const_cast<PWSTR>(L"\\cleanup-fast.txt"), 0);
    });

    const auto completed_without_global_lock =
        cleanup_future.wait_for(std::chrono::milliseconds(250)) == std::future_status::ready;
    mutation_lock.unlock();
    cleanup_future.wait();

    return Require(
        completed_without_global_lock &&
            file->open_handle_count == 0 &&
            cleanup_context->cleanup_seen &&
            context.last_foreground_mutation_tick_ms.load(std::memory_order_acquire) != 0,
        "Non-delete cleanup should not wait for the global mutation callback queue");
}

bool TestDeferredCloseDrainsOnFlushBeforeSuccess()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    ScopeExit clear_writeback_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
    }};

    MountContext context{};
    if (!ConfigureNativeCommitFailureForUnitTest(context))
    {
        return true;
    }
    if (!Require(PrepareUnitHydrationRoot(context, L"deferred-close-flush-drain"), "Deferred flush test should prepare cache root"))
    {
        return false;
    }
    if (!Require(ConfigureUnitRecoveryMarker(context, L"deferred-close-flush-drain"), "Deferred flush test should configure a recovery marker"))
    {
        return false;
    }
    ScopeExit cleanup{[&]()
    {
        StopDeferredCommitWorker(&context);
        std::error_code ec;
        std::filesystem::remove(context.recovery_marker_file, ec);
        std::filesystem::remove_all(context.session_root, ec);
    }};

    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);

    std::shared_ptr<Node> file;
    if (!Require(SeedResizableUnitFile(context, file), "Deferred flush test should seed hydration file"))
    {
        return false;
    }

    auto fs = BuildFileSystem(&context);
    auto* close_context = new OpenContext();
    if (!Require(OpenResizableUnitFile(context, file, *close_context), "Deferred flush test should open hydration file"))
    {
        delete close_context;
        return false;
    }
    close_context->write_open = true;
    file->open_handle_count = 1;
    file->write_handle_count = 1;

    FSP_FSCTL_FILE_INFO info{};
    if (!Require(WriteUnitContent(fs, close_context, info), "Deferred flush test should stage a content write"))
    {
        CloseHandle(close_context->file);
        close_context->file = INVALID_HANDLE_VALUE;
        delete close_context;
        return false;
    }
    CB_Close(&fs, close_context);
    if (!Require(context.test_native_commit_attempt_count == 0, "Deferred flush test should not commit at close"))
    {
        return false;
    }

    OpenContext flush_context{};
    flush_context.node = file;
    const auto flush_status = CB_Flush(&fs, &flush_context, &info);
    return Require(
        flush_status == STATUS_MEDIA_WRITE_PROTECTED &&
            context.test_native_commit_attempt_count == 1 &&
            context.recovery_active &&
            !context.native_write_enabled,
        "Flush should synchronously drain deferred close commits before returning");
#else
    return true;
#endif
}

