bool TestDeferredDirectoryRenameOpenDescendantFallbackReadsOldCommittedPath()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_NAMESPACE_WRITEBACK", nullptr);
    ScopeExit clear_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_NAMESPACE_WRITEBACK", nullptr);
    }};

    MountContext context{};
    context.args.volume = L"Main";
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_require_canonical_commit = false;
    context.args.write_disallow_scaffold_commit_on_non_fixture = false;
    context.args.write_reject_scaffold_replay_blob_on_non_fixture = false;
    context.args.write_require_canonical_replay_candidate_on_non_fixture = false;
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);
    if (!Require(PrepareUnitHydrationRoot(context, L"deferred-directory-rename-immediate-read"), "Deferred directory rename immediate-read test should prepare cache root") ||
        !Require(ConfigureUnitRecoveryMarker(context, L"deferred-directory-rename-immediate-read"), "Deferred directory rename immediate-read test should configure recovery marker"))
    {
        return false;
    }

    std::error_code ec;
    ScopeExit cleanup{[&]()
    {
        StopDeferredCommitWorker(&context);
        std::filesystem::remove(context.recovery_marker_file, ec);
        std::filesystem::remove_all(context.session_root, ec);
    }};

    const auto image_path = context.session_root / "deferred-directory-rename-immediate-read.apfs.img";
    if (!Require(CreateSyntheticApfsContainerForTest(image_path, 4096), "Deferred directory rename immediate-read test should create synthetic APFS image"))
    {
        return false;
    }
    context.args.device = image_path.wstring();

    apfsaccess::rw::MetadataStore::VolumeContext rw_context
    {
        image_path.wstring(),
        L"Main",
    };
    rw_context.allow_legacy_scaffold_for_fixtures = true;
    rw_context.disallow_scaffold_commit_on_non_fixture = false;
    rw_context.reject_scaffold_replay_blob_on_non_fixture = false;
    rw_context.require_canonical_replay_candidate_on_non_fixture = false;
    context.metadata_store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));

    const auto committed_payload = BuildPatternPayloadForTest(64 * 1024, 0x38);
    std::unordered_map<std::wstring, std::vector<std::byte>> staged_payloads;
    context.metadata_store->SetFilePayloadProvider(
        [&staged_payloads](const std::wstring& path, std::uint64_t logical_size) -> std::optional<std::vector<std::byte>>
        {
            auto pending = staged_payloads.find(path);
            if (pending == staged_payloads.end())
            {
                return std::nullopt;
            }
            auto payload = pending->second;
            payload.resize(static_cast<std::size_t>(logical_size), std::byte{0});
            return payload;
        });

    {
        std::lock_guard<std::mutex> metadata_lock(context.metadata_mutex);
        if (!Require(context.metadata_store->LoadContainerSuperblocks(), "Deferred directory rename immediate-read test should load container superblocks") ||
            !Require(context.metadata_store->LoadObjectMap(), "Deferred directory rename immediate-read test should load object map") ||
            !Require(context.metadata_store->LoadSpacemanState(), "Deferred directory rename immediate-read test should load spaceman state") ||
            !Require(context.metadata_store->PrepareNativeWritePath(), "Deferred directory rename immediate-read test should prepare native write path"))
        {
            return false;
        }

        apfsaccess::rw::MetadataStore::MutationRequest create_dir{};
        create_dir.operation = apfsaccess::rw::MetadataStore::MutationOperation::CreateDirectory;
        create_dir.path = L"\\source";
        if (!Require(
                context.metadata_store->ApplyMutation(create_dir) == apfsaccess::rw::MetadataStore::MutationStatus::Applied,
                "Deferred directory rename immediate-read test should create committed source directory"))
        {
            return false;
        }

        apfsaccess::rw::MetadataStore::MutationRequest create_child{};
        create_child.operation = apfsaccess::rw::MetadataStore::MutationOperation::CreateDirectory;
        create_child.path = L"\\source\\child";
        if (!Require(
                context.metadata_store->ApplyMutation(create_child) == apfsaccess::rw::MetadataStore::MutationStatus::Applied,
                "Deferred directory rename immediate-read test should create committed child directory"))
        {
            return false;
        }

        apfsaccess::rw::MetadataStore::MutationRequest create_file{};
        create_file.operation = apfsaccess::rw::MetadataStore::MutationOperation::CreateFile;
        create_file.path = L"\\source\\child\\file.bin";
        if (!Require(
                context.metadata_store->ApplyMutation(create_file) == apfsaccess::rw::MetadataStore::MutationStatus::Applied,
                "Deferred directory rename immediate-read test should create committed child file"))
        {
            return false;
        }

        staged_payloads[L"\\source\\child\\file.bin"] = committed_payload;
        apfsaccess::rw::MetadataStore::MutationRequest write_file{};
        write_file.operation = apfsaccess::rw::MetadataStore::MutationOperation::Write;
        write_file.path = L"\\source\\child\\file.bin";
        write_file.length = committed_payload.size();
        if (!Require(
                context.metadata_store->ApplyMutation(write_file) == apfsaccess::rw::MetadataStore::MutationStatus::Applied,
                "Deferred directory rename immediate-read test should stage committed payload") ||
            !Require(
                context.metadata_store->CommitPendingMutations() == apfsaccess::rw::MetadataStore::CommitStatus::Committed,
                "Deferred directory rename immediate-read test should commit source subtree"))
        {
            return false;
        }
    }

    if (!Require(MergeLastCommittedInodeChangesIntoNodeIndex(&context), "Deferred directory rename immediate-read test should merge committed inode changes"))
    {
        return false;
    }

    auto source_file = FindNode(&context, L"\\source\\child\\file.bin");
    if (!Require(source_file != nullptr, "Deferred directory rename immediate-read test should expose committed source file"))
    {
        return false;
    }
    std::filesystem::remove(HydrationPath(&context, *source_file), ec);
    ec.clear();

    auto fs = BuildFileSystem(&context);
    const auto rename_status = CB_Rename(
        &fs,
        nullptr,
        const_cast<PWSTR>(L"\\source"),
        const_cast<PWSTR>(L"\\renamed"),
        FALSE);
    auto renamed_file = FindNode(&context, L"\\renamed\\child\\file.bin");
    if (!Require(
            rename_status == STATUS_SUCCESS &&
                renamed_file != nullptr &&
                context.test_native_commit_attempt_count == 0 &&
                context.close_commit_deferred.load(std::memory_order_acquire) &&
                renamed_file->committed_read_path == L"\\source\\child\\file.bin",
            "Deferred directory rename immediate-read test should preserve descendant file committed path"))
    {
        return false;
    }

    PVOID read_ctx = nullptr;
    FSP_FSCTL_FILE_INFO read_info{};
    const auto open_status = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\renamed\\child\\file.bin"),
        FILE_NON_DIRECTORY_FILE,
        FILE_READ_DATA,
        &read_ctx,
        &read_info);
    if (!Require(open_status == STATUS_SUCCESS && read_ctx != nullptr, "Deferred directory-renamed file should open for immediate read"))
    {
        return false;
    }
    auto* read_open_context = reinterpret_cast<OpenContext*>(read_ctx);
    if (!Require(
            context.test_native_commit_attempt_count == 0 &&
                context.close_commit_deferred.load(std::memory_order_acquire) &&
                read_open_context->metadata_read_fallback,
            "Deferred directory-renamed read-open should use committed-path fallback without draining"))
    {
        CB_Close(&fs, read_ctx);
        return false;
    }

    std::array<char, 64> buffer{};
    ULONG read_done = 0;
    const auto read_offset = static_cast<UINT64>(2048);
    const auto read_status = CB_Read(
        &fs,
        read_ctx,
        buffer.data(),
        read_offset,
        static_cast<ULONG>(buffer.size()),
        &read_done);
    CB_Close(&fs, read_ctx);
    if (!Require(read_status == STATUS_SUCCESS, "Deferred directory-renamed file should read through old committed path") ||
        !Require(read_done == buffer.size(), "Deferred directory-renamed file should return requested bytes"))
    {
        return false;
    }
    for (std::size_t index = 0; index < buffer.size(); ++index)
    {
        const auto expected = committed_payload[static_cast<std::size_t>(read_offset) + index];
        if (!Require(static_cast<std::byte>(static_cast<unsigned char>(buffer[index])) == expected, "Deferred directory-renamed file bytes should match committed source bytes"))
        {
            return false;
        }
    }

    OpenContext flush_context{};
    flush_context.node = context.nodes.at(Key(L"\\"));
    FSP_FSCTL_FILE_INFO flush_info{};
    const auto flush_status = CB_Flush(&fs, &flush_context, &flush_info);
    return Require(
        flush_status == STATUS_SUCCESS &&
            !context.close_commit_deferred.load(std::memory_order_acquire) &&
            context.deferred_rename_rollback_plans.empty() &&
            renamed_file->committed_read_path.empty(),
        "Flush should commit deferred directory rename and clear descendant committed read path");
#else
    return true;
#endif
}

