bool TestExperimentalDualHydrationMirrorSwitch()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_DUAL_HYDRATION_MIRROR", nullptr);
    ScopeExit clear_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_DUAL_HYDRATION_MIRROR", nullptr);
    }};

    if (!Require(!IsExperimentalDualHydrationMirrorEnabled(),
            "Dual hydration mirror should remain disabled by default"))
    {
        return false;
    }
    SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_DUAL_HYDRATION_MIRROR", L"1");
    if (!Require(IsExperimentalDualHydrationMirrorEnabled(),
            "Dual hydration mirror should support an explicit opt-in"))
    {
        return false;
    }
    SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_DUAL_HYDRATION_MIRROR", L"0");
    return Require(!IsExperimentalDualHydrationMirrorEnabled(),
        "Dual hydration mirror should honor an explicit zero value");
#else
    return true;
#endif
}

bool TestCloseDeleteNoopWhenShutdownDrainActive()
{
    MountContext context{};
    context.overlay_write_enabled = true;
    context.mutation_admission_state.store(kMutationAdmissionDrainFlag, std::memory_order_release);
    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);

    auto root = context.nodes.at(Key(L"\\"));
    AddChildName(root->children, L"drain_close.txt");
    auto file = MakeNode(L"\\drain_close.txt", false, false);
    file->open_handle_count = 1;
    file->write_handle_count = 1;
    file->delete_intent_count = 1;
    file->delete_latched = true;
    file->delete_pending = true;
    context.open_write_handle_count.store(1, std::memory_order_release);
    context.nodes.emplace(Key(file->path), file);

    auto* open_context = new OpenContext();
    open_context->node = file;
    open_context->write_open = true;
    open_context->allow_delete = true;
    open_context->delete_on_cleanup = true;

    auto fs = BuildFileSystem(&context);
    CB_Close(&fs, open_context);

    if (!Require(
            context.nodes.find(Key(L"\\drain_close.txt")) != context.nodes.end() &&
                HasChildName(root->children, L"drain_close.txt"),
            "Close after shutdown admission closes must not start delete mutation work"))
    {
        return false;
    }

    if (!Require(
            file->open_handle_count == 0 &&
                file->write_handle_count == 0 &&
                context.open_write_handle_count.load(std::memory_order_acquire) == 0,
            "Rejected close mutation should still release open-handle accounting"))
    {
        return false;
    }

    if (!Require(
            !file->delete_pending &&
                !file->delete_latched &&
                file->delete_intent_count == 0,
            "Rejected close mutation should roll back transient delete disposition state"))
    {
        return false;
    }

    return Require(
        MutationAdmissionCount(context.mutation_admission_state.load(std::memory_order_acquire)) == 0,
        "Rejected close mutation should not leak external mutation admission");
}

