bool TestDeferredBarrierRechecksCurrentWalWatermark()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"deferred-barrier-watermark-race-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "Deferred barrier watermark race test should create its temp directory"))
    {
        return false;
    }

    MountContext context{};
    ConfigureGroupedAcceptanceTestContext(
        context,
        run_root,
        "deferred-barrier-watermark-race-volume",
        1,
        5);
    context.recovery_marker_file = run_root / "recovery.marker";
    ScopeExit cleanup{[&]()
    {
        context.tx_manager.reset();
        context.payload_spool.reset();
        std::filesystem::remove_all(run_root, ec);
    }};

    if (!Require(
            StageGroupedAcceptancePayloadForTest(
                context,
                L"\\deferred-barrier-watermark-race.bin",
                7905,
                std::byte{0xa5}),
            "Deferred barrier watermark race test should stage payload"))
    {
        return false;
    }
    std::uint64_t accepted_sequence = 0;
    if (!Require(
            AcceptMutationJournalForDeferredCommitBestEffort(
                &context,
                L"DeferredBarrierWatermarkRaceAccept",
                &accepted_sequence),
            "Deferred barrier watermark race test should publish accepted evidence"))
    {
        return false;
    }

    std::unique_lock<std::mutex> deferred_lock(context.deferred_commit_mutex);
    context.deferred_commit_in_flight = true;
    context.deferred_commit_in_flight_target = accepted_sequence;
    std::atomic<bool> completion_entered = false;
    bool effective_success = false;
    auto completion = std::async(std::launch::async, [&]()
    {
        completion_entered.store(true, std::memory_order_release);
        return CompleteDeferredCommitBarrier(
            &context,
            true,
            STATUS_SUCCESS,
            &effective_success);
    });

    const auto entry_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while (!completion_entered.load(std::memory_order_acquire) &&
           std::chrono::steady_clock::now() < entry_deadline)
    {
        std::this_thread::yield();
    }
    std::this_thread::sleep_for(std::chrono::milliseconds(150));

    bool durable_marked = false;
    {
        std::lock_guard<std::mutex> tx_lock(context.tx_mutex);
        durable_marked = context.tx_manager &&
            context.tx_manager->MarkApfsDurableThrough(accepted_sequence);
    }
    deferred_lock.unlock();

    const auto completion_recorded = completion.get();
    std::uint64_t completed_target = 0;
    std::uint64_t failed_target = 0;
    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        completed_target = context.deferred_commit_completed_target;
        failed_target = context.deferred_commit_failed_target;
    }
    return Require(
               completion_entered.load(std::memory_order_acquire),
               "Deferred barrier completion should enter while its state lock is held") &&
           Require(durable_marked, "Concurrent finalization should advance the current APFS-durable watermark") &&
           Require(
               completion_recorded && effective_success,
               "Barrier completion must use the current watermark instead of a stale pre-lock snapshot") &&
           Require(
               completed_target == accepted_sequence && failed_target == 0,
               "Current durable evidence should complete the target without latching a false failure");
#else
    return true;
#endif
}

bool TestCommittedMetadataDoesNotClearUnfinalizedWal()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"journal-finalization-fail-closed-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "Journal finalization failure test should create its temp directory"))
    {
        return false;
    }

    MountContext context{};
    ConfigureGroupedAcceptanceTestContext(
        context,
        run_root,
        "journal-finalization-fail-closed-volume",
        1,
        5);
    context.args.status_file = (run_root / "status.json").wstring();
    context.recovery_marker_file = run_root / "recovery.marker";
    context.test_forced_native_commit_status =
        apfsaccess::rw::MetadataStore::CommitStatus::Committed;
    ScopeExit cleanup{[&]()
    {
        context.tx_manager.reset();
        context.payload_spool.reset();
        std::filesystem::remove_all(run_root, ec);
    }};

    if (!Require(
            StageGroupedAcceptancePayloadForTest(
                context,
                L"\\journal-finalization-fail-closed.bin",
                7901,
                std::byte{0xd1}),
            "Journal finalization failure test should stage payload"))
    {
        return false;
    }
    std::uint64_t accepted_sequence = 0;
    if (!Require(
            AcceptMutationJournalForDeferredCommitBestEffort(
                &context,
                L"JournalFinalizationFailClosedAccept",
                &accepted_sequence),
            "Journal finalization failure test should publish accepted evidence"))
    {
        return false;
    }

    context.recovery_active = true;
    context.write_degraded = false;
    context.runtime_recovery_reason = L"AwaitingJournalFinalization";
    context.runtime_last_recovery_action = L"RetainedUntilJournalFinalization";
    const auto commit_status = CommitNativeMutationsBestEffort(
        &context,
        L"JournalFinalizationFailClosedCommit");
    std::ifstream unfinalized_marker_input(context.recovery_marker_file, std::ios::binary);
    const std::string unfinalized_marker_text{
        std::istreambuf_iterator<char>(unfinalized_marker_input),
        std::istreambuf_iterator<char>()};
    if (!Require(NT_SUCCESS(commit_status), "Forced APFS checkpoint should succeed") ||
        !Require(
            context.recovery_active && !context.write_degraded && context.native_write_enabled &&
                context.runtime_recovery_reason == L"AwaitingJournalFinalization",
            "Committed metadata must retain recovery state until WAL finalization is proven") ||
        !Require(
            unfinalized_marker_text.find("dirty=1") != std::string::npos,
            "Committed metadata must keep the recovery marker dirty while WAL acceptance is unresolved"))
    {
        return false;
    }

    bool durable_flush_fault_invoked = false;
    context.tx_manager->SetJournalFaultInjectionHook([&](std::string_view stage)
    {
        if (stage == "durable-flush")
        {
            durable_flush_fault_invoked = true;
            return true;
        }
        return false;
    });
    const auto finalized = FinalizeMutationJournalBestEffort(
        &context,
        L"JournalFinalizationFailClosed");
    context.tx_manager->SetJournalFaultInjectionHook({});
    const auto watermarks = context.tx_manager->Watermarks();
    const auto journal_evidence = apfsaccess::rw::WriteAheadLog::ReadAll(
        context.tx_journal_file,
        context.payload_spool_volume_identity);
    const auto has_accepted_wal_evidence = std::any_of(
        journal_evidence.records.begin(),
        journal_evidence.records.end(),
        [](const auto& record)
        {
            return record.operation == apfsaccess::rw::WriteAheadLog::OperationKind::TransactionMarker &&
                record.state == apfsaccess::rw::WriteAheadLog::RecordState::Accepted;
        });
    std::ifstream marker_input(context.recovery_marker_file, std::ios::binary);
    const std::string marker_text{
        std::istreambuf_iterator<char>(marker_input),
        std::istreambuf_iterator<char>()};
    std::ifstream status_input(context.args.status_file, std::ios::binary);
    const std::string status_text{
        std::istreambuf_iterator<char>(status_input),
        std::istreambuf_iterator<char>()};

    std::lock_guard<std::recursive_mutex> runtime_lock(context.runtime_state_mutex);
    return Require(durable_flush_fault_invoked, "Journal finalization failure must invoke the durable-flush fault hook") &&
           Require(!finalized, "Ambiguous WAL durability append must fail finalization") &&
           Require(!context.tx_manager->RecoveryStateValid(), "Ambiguous WAL durability append must invalidate transaction recovery state") &&
           Require(
               accepted_sequence != 0 &&
                   watermarks.accepted_sequence == accepted_sequence &&
                   watermarks.apfs_durable_sequence < accepted_sequence,
               "Failed finalization must retain accepted evidence without publishing an APFS watermark") &&
           Require(
               journal_evidence.status == apfsaccess::rw::WriteAheadLog::ReadStatus::Ok &&
                   journal_evidence.records.size() >= 2 &&
                   has_accepted_wal_evidence,
               "Failed finalization must retain readable accepted WAL evidence") &&
           Require(
               context.recovery_active && context.pending_native_writes && context.write_degraded,
               "Failed finalization must re-arm pending recovery state") &&
           Require(
               !context.native_write_enabled && !context.overlay_write_enabled,
               "Fail-closed finalization failure must disable all mutation backends") &&
           Require(
               context.runtime_recovery_reason == L"JournalFinalizationFailed" &&
                   context.runtime_last_recovery_action == L"RetainedAfterJournalFinalizationFailure",
               "Failed finalization must publish a specific recovery reason and action") &&
           Require(
               marker_text.find("dirty=1") != std::string::npos,
               "Failed finalization must durably re-arm the recovery marker") &&
           Require(
               status_text.find("\"recoveryActive\":true") != std::string::npos &&
                   status_text.find("\"walRecoveryStateValid\":false") != std::string::npos &&
                   status_text.find("\"walAcceptedSequence\":" + std::to_string(accepted_sequence)) != std::string::npos,
               "Failed finalization must publish dirty recovery state in the host status output");
#else
    return true;
#endif
}

bool TestFinalizationReportsUnmetDeferredDurabilityTarget()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"finalization-barrier-target-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "Deferred durability barrier test should create its temp directory"))
    {
        return false;
    }

    MountContext context{};
    ConfigureGroupedAcceptanceTestContext(
        context,
        run_root,
        "finalization-barrier-target-volume",
        1,
        5);
    context.args.write_recovery_policy = L"BestEffort";
    context.overlay_write_enabled = true;
    context.recovery_marker_file = run_root / "recovery.marker";
    ScopeExit cleanup{[&]()
    {
        context.tx_manager.reset();
        context.payload_spool.reset();
        std::filesystem::remove_all(run_root, ec);
    }};

    if (!Require(
            StageGroupedAcceptancePayloadForTest(
                context,
                L"\\finalization-barrier-target.bin",
                7903,
                std::byte{0xf1}),
            "Deferred durability barrier test should stage payload"))
    {
        return false;
    }
    std::uint64_t accepted_sequence = 0;
    if (!Require(
            AcceptMutationJournalForDeferredCommitBestEffort(
                &context,
                L"DeferredDurabilityBarrierAccept",
                &accepted_sequence),
            "Deferred durability barrier test should publish accepted evidence"))
    {
        return false;
    }

    const auto unmet_target = accepted_sequence + 1;
    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        context.deferred_commit_in_flight = true;
        context.deferred_commit_in_flight_target = unmet_target;
    }
    const auto finalized = FinalizeMutationJournalBestEffort(
        &context,
        L"DeferredDurabilityBarrierFinalize");
    const auto watermarks = context.tx_manager->Watermarks();
    std::uint64_t failed_target = 0;
    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        failed_target = context.deferred_commit_failed_target;
    }

    std::lock_guard<std::recursive_mutex> runtime_lock(context.runtime_state_mutex);
    return Require(!finalized, "Finalization must fail when its deferred target is not APFS-durable") &&
           Require(
               watermarks.accepted_sequence == accepted_sequence &&
                   watermarks.apfs_durable_sequence == accepted_sequence &&
                   watermarks.cleanup_sequence == accepted_sequence,
               "Barrier-target failure should preserve the actual WAL durability watermarks") &&
           Require(failed_target == unmet_target, "Barrier-target failure should retain the unresolved target") &&
           Require(
               context.recovery_active && context.pending_native_writes &&
                   context.runtime_recovery_reason == L"DeferredCommitDurabilityNotReached",
               "Barrier-target failure should retain an explicit recovery state") &&
           Require(
               context.native_write_enabled && context.overlay_write_enabled,
               "BestEffort barrier-target failure should preserve configured backends while recovery is active");
#else
    return true;
#endif
}

bool TestShutdownFailedCommitRetainsAcceptedEvidence()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"shutdown-failed-commit-retains-" + std::to_wstring(GetTickCount64()));
    if (ec)
    {
        return Require(false, "Shutdown failed-commit test should resolve temp directory");
    }
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "Shutdown failed-commit test should create temp directory"))
    {
        return false;
    }

    MountContext context{};
    ConfigureGroupedAcceptanceTestContext(
        context,
        run_root,
        "shutdown-failed-commit-volume",
        1,
        5);
    ScopeExit cleanup{[&]()
    {
        RequestGroupedDeferredAcceptanceFinish(&context);
        StopDeferredCommitWorker(&context);
        context.tx_manager.reset();
        context.payload_spool.reset();
        std::filesystem::remove_all(run_root, ec);
    }};

    if (!Require(
            StageGroupedAcceptancePayloadForTest(
                context,
                L"\\shutdown-failed-commit.bin",
                7801,
                std::byte{0x91}),
            "Shutdown failed-commit test should stage accepted payload"))
    {
        return false;
    }

    std::uint64_t accepted_sequence = 0;
    if (!Require(
            AcceptMutationJournalForDeferredCommitBestEffort(
                &context,
                L"ShutdownFailedCommitAccept",
                &accepted_sequence),
            "Shutdown failed-commit test should publish accepted evidence"))
    {
        return false;
    }

    // Model the real post-commit-failure transition: the APFS commit failed,
    // the mount is fail-closed, and the accepted WAL/spool evidence remains.
    context.native_write_enabled = false;
    context.overlay_write_enabled = false;
    context.recovery_active = true;
    context.write_degraded = true;

    const auto drain_status = DrainNativeMutationsByPolicy(&context, L"Shutdown");
    const auto finalize_status = FinalizeMutationJournalBestEffort(&context, L"Shutdown");
    const auto watermarks = context.tx_manager->Watermarks();
    const auto spool = context.payload_spool->SnapshotCounters();

    return Require(
               !NT_SUCCESS(drain_status),
               "Shutdown must fail when accepted evidence remains after a failed APFS commit") &&
           Require(
               !finalize_status,
               "Shutdown finalization must not claim success for unresolved accepted evidence") &&
           Require(
               watermarks.apfs_durable_sequence < accepted_sequence &&
                   watermarks.cleanup_sequence < accepted_sequence,
               "Failed shutdown must retain APFS-durable and cleanup watermarks below the accepted target") &&
           Require(
               spool.dirty_range_count != 0,
               "Failed shutdown must retain payload-spool evidence for replay");
#else
    return true;
#endif
}

