bool TestShutdownUnresolvedCleanupWatermarkFailsClosed()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    ScopeExit clear_defer_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
    }};

    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"shutdown-unresolved-cleanup-" + std::to_wstring(GetTickCount64()));
    if (ec)
    {
        return Require(false, "Shutdown cleanup-watermark test should resolve temp directory");
    }
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "Shutdown cleanup-watermark test should create temp directory"))
    {
        return false;
    }

    MountContext context{};
    ConfigureGroupedAcceptanceTestContext(
        context,
        run_root,
        "shutdown-unresolved-cleanup-volume",
        1,
        5);
    context.test_forced_native_commit_status =
        apfsaccess::rw::MetadataStore::CommitStatus::Committed;
    ScopeExit cleanup{[&]()
    {
        std::filesystem::remove_all(
            context.payload_spool->SpoolFilePath(),
            ec);
        RequestGroupedDeferredAcceptanceFinish(&context);
        StopDeferredCommitWorker(&context);
        context.tx_manager.reset();
        context.payload_spool.reset();
        std::filesystem::remove_all(run_root, ec);
    }};

    if (!Require(
            StageGroupedAcceptancePayloadForTest(
                context,
                L"\\shutdown-unresolved-cleanup.bin",
                7804,
                std::byte{0xc1}),
            "Shutdown cleanup-watermark test should stage payload"))
    {
        return false;
    }

    std::uint64_t accepted_sequence = 0;
    if (!Require(
            AcceptMutationJournalForDeferredCommitBestEffort(
                &context,
                L"ShutdownCleanupWatermarkAccept",
                &accepted_sequence),
            "Shutdown cleanup-watermark test should publish accepted evidence"))
    {
        return false;
    }
    if (!Require(
            context.payload_spool->FlushDirtyState(),
            "Shutdown cleanup-watermark test should establish a clean index before fault injection"))
    {
        return false;
    }

    const auto blocked_spool = context.payload_spool->SpoolFilePath();
    const auto retained_spool_evidence = blocked_spool.wstring() + L".retained";
    std::filesystem::rename(blocked_spool, retained_spool_evidence, ec);
    if (!Require(!ec, "Shutdown cleanup-watermark test should retain spool evidence before blocking removal"))
    {
        return false;
    }
    std::filesystem::create_directories(blocked_spool / "blocker", ec);
    if (!Require(!ec, "Shutdown cleanup-watermark test should block spool removal"))
    {
        return false;
    }

    const auto initial_drain_status = DrainNativeMutationsByPolicy(&context, L"Shutdown");
    const auto first_finalize_ok = FinalizeMutationJournalBestEffort(&context, L"Shutdown");
    const auto first_watermarks = context.tx_manager->Watermarks();
    const auto first_spool = context.payload_spool->SnapshotCounters();
    if (!Require(
            NT_SUCCESS(initial_drain_status),
            "Shutdown cleanup-watermark test should complete the initial APFS drain") ||
        !Require(
            !first_finalize_ok,
            "Shutdown cleanup-watermark test should fail when spool cleanup cannot publish its index") ||
        !Require(
            first_watermarks.accepted_sequence == accepted_sequence &&
                first_watermarks.apfs_durable_sequence == accepted_sequence &&
                first_watermarks.cleanup_sequence < accepted_sequence,
            "Cleanup failure must retain accepted and APFS-durable watermarks while cleanup lags") ||
        !Require(
            first_spool.dirty_range_count != 0 && first_spool.cleanup_failures != 0,
            "Cleanup failure must retain dirty payload evidence and increment cleanup failures"))
    {
        return false;
    }

    const auto later_drain_status = DrainNativeMutationsByPolicy(&context, L"Shutdown");
    const auto later_finalize_ok = FinalizeMutationJournalBestEffort(&context, L"Shutdown");
    const auto later_watermarks = context.tx_manager->Watermarks();
    const auto later_spool = context.payload_spool->SnapshotCounters();
    const auto shutdown_exit = ResolveFsHostShutdownExitCode(
        true,
        later_drain_status,
        later_finalize_ok);
    std::lock_guard<std::recursive_mutex> runtime_lock(context.runtime_state_mutex);
    return Require(
               NT_SUCCESS(later_drain_status),
               "A later shutdown drain should still be able to retry cleanup") &&
           Require(
               !later_finalize_ok && shutdown_exit != 0,
               "Shutdown must remain fail-closed while the cleanup watermark is unresolved") &&
           Require(
               later_watermarks.cleanup_sequence < accepted_sequence &&
                   later_spool.dirty_range_count != 0 &&
                   later_spool.cleanup_failures > first_spool.cleanup_failures,
               "A later shutdown must retry cleanup and retain evidence after another failure") &&
           Require(
               context.recovery_active && context.write_degraded &&
                   !context.native_write_enabled && !context.overlay_write_enabled &&
                   context.runtime_recovery_reason == L"PayloadSpoolCleanupFailed",
               "Unresolved cleanup must keep the mount degraded with an explicit recovery reason");
#else
    return true;
#endif
}

