bool WaitForGroupedAcceptanceParticipants(
    const MountContext& context,
    std::uint32_t participants,
    std::chrono::milliseconds timeout = std::chrono::seconds(2))
{
    const auto deadline = std::chrono::steady_clock::now() + timeout;
    while (context.grouped_acceptance_waiting_participants.load(std::memory_order_acquire) != participants &&
           std::chrono::steady_clock::now() < deadline)
    {
        std::this_thread::yield();
    }
    return context.grouped_acceptance_waiting_participants.load(std::memory_order_acquire) == participants;
}

