bool TestSerialDeferredProcessKillBeforeWalFlushHasNoFalseDurability()
{
    g_serial_deferred_safety_registrations.fetch_or(
        SerialPreDurableKillIsTruthful,
        std::memory_order_relaxed);
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"serial-pre-durable-kill-" + std::to_wstring(GetCurrentProcessId()) + L"-" +
            std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (!Require(
            !ec && CreateSyntheticApfsContainerForTest(
                run_root / "accepted-write-kill.apfs.img"),
            "Pre-durable process-kill test should prepare its fixture"))
    {
        return false;
    }

    const auto child_reached_boundary = LaunchAndKillAcceptedWriteChild(
        run_root,
        "inline-wal-appended-undurable",
        0);
    const auto spool_root = run_root / "spool";
    auto store = MakeAcceptedWriteKillStore(run_root / "accepted-write-kill.apfs.img");
    auto tx = std::make_unique<apfsaccess::rw::TransactionManager>(L"DeferredContent");
    tx->SetVolumeIdentity(kAcceptedWriteKillVolumeIdentityWide);
    tx->SetJournalPath((spool_root / "write-ahead.wal").wstring());
    const auto watermarks = tx->Watermarks();

    std::vector<std::byte> committed_payload;
    const auto exposes_new_payload = store &&
        store->ReadCommittedFileRange(
            kAcceptedWriteKillPath,
            0,
            AcceptedWriteKillPayload().size(),
            committed_payload) &&
        committed_payload == std::vector<std::byte>(
            AcceptedWriteKillPayload().begin(),
            AcceptedWriteKillPayload().end());

    bool accepted_recovery_is_truthful = true;
    if (tx->RecoveryStateValid() && watermarks.accepted_sequence != 0)
    {
        std::vector<apfsaccess::rw::TransactionManager::AcceptedTransaction> accepted;
        std::string failure_reason;
        accepted_recovery_is_truthful =
            tx->HasUnappliedAcceptedWork() &&
            tx->LoadUnappliedAcceptedTransactions(accepted, &failure_reason) &&
            failure_reason.empty() &&
            accepted.size() == 1 &&
            accepted.front().mutations.size() == 1 &&
            accepted.front().mutations.front().inline_payload ==
                std::vector<std::byte>(
                    AcceptedWriteKillPayload().begin(),
                    AcceptedWriteKillPayload().end());
    }

    const auto ok =
        Require(child_reached_boundary, "Child should reach queue-only acceptance before termination") &&
        Require(store != nullptr, "Pre-durable process-kill state should reopen its APFS fixture") &&
        Require(!exposes_new_payload, "Pre-durable process termination must not expose uncommitted payload as APFS-durable") &&
        Require(
            watermarks.apfs_durable_sequence == 0 && watermarks.cleanup_sequence == 0,
            "Pre-durable process termination must not publish APFS or cleanup durability") &&
        Require(
            accepted_recovery_is_truthful,
            "Surviving accepted WAL must remain unapplied and exactly inline-recoverable");
    if (ok)
    {
        tx.reset();
        store.reset();
        std::filesystem::remove_all(run_root, ec);
    }
    else
    {
        std::wcerr << L"[DIAG] Pre-durable process-kill evidence retained at "
                   << run_root.wstring() << std::endl;
    }
    return ok;
#else
    return true;
#endif
}

