bool TestRecoveryMarkerFinalizeFailureIsNotCached()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = (std::filesystem::temp_directory_path() / L"ApfsAccessRecoveryMarkerTests") /
        (std::to_wstring(GetCurrentProcessId()) + L"-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "Recovery marker finalization test should create its D-drive scratch root"))
    {
        return false;
    }
    ScopeExit cleanup{[&]() { std::filesystem::remove_all(run_root, ec); }};

    MountContext context{};
    const auto marker_path = run_root / "recovery.marker";
    RecoveryMarkerState dirty{};
    dirty.dirty = true;
    dirty.last_commit_xid = 17;
    if (!Require(PersistRecoveryMarkerState(&context, marker_path, dirty),
            "Recovery marker finalization test should persist its initial dirty marker"))
    {
        return false;
    }

    RecoveryMarkerState clean{};
    clean.dirty = false;
    clean.last_commit_xid = 17;
    context.test_force_recovery_marker_finalize_failure = true;
    RecoveryMarkerState retained{};
    return Require(!PersistRecoveryMarkerState(&context, marker_path, clean),
               "Recovery marker persistence must report a late stream finalization failure") &&
           Require(context.last_recovery_marker_dirty == std::optional<bool>(true) &&
                       context.last_recovery_marker_commit_xid == dirty.last_commit_xid,
               "A failed marker finalization must not update the cached marker state") &&
           Require(TryLoadRecoveryMarkerState(marker_path, retained) &&
                       retained.dirty &&
                       retained.last_commit_xid == dirty.last_commit_xid,
               "A failed marker replacement must preserve the prior durable dirty marker");
#else
    return true;
#endif
}

