bool TestRepeatedRecoveryMarkerUpdatesSkipUnchangedState()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = (std::filesystem::temp_directory_path() / L"ApfsAccessRecoveryMarkerTests") /
        (L"unchanged-state-" + std::to_wstring(GetCurrentProcessId()) + L"-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "Unchanged marker-state test should create its D-drive scratch root"))
    {
        return false;
    }
    ScopeExit cleanup{[&]() { std::filesystem::remove_all(run_root, ec); }};

    MountContext context{};
    context.recovery_marker_file = run_root / "recovery.marker";
    context.runtime_last_commit_xid = 37;
    if (!Require(
            UpdateRecoveryMarkerBestEffort(&context, true),
            "Unchanged marker-state test should persist its initial dirty marker"))
    {
        return false;
    }

    const auto first_count = context.perf_recovery_marker.count.load(std::memory_order_relaxed);
    if (!Require(
            UpdateRecoveryMarkerBestEffort(&context, true),
            "Unchanged marker-state test should accept a repeated dirty update"))
    {
        return false;
    }
    if (!Require(
            context.perf_recovery_marker.count.load(std::memory_order_relaxed) == first_count,
            "Repeated dirty marker updates should skip the expensive marker validation path"))
    {
        return false;
    }

    std::filesystem::remove(context.recovery_marker_file, ec);
    if (!Require(!ec, "Unchanged marker-state test should remove its marker to simulate external loss") ||
        !Require(
            UpdateRecoveryMarkerBestEffort(&context, true),
            "A missing marker must be recreated even when its in-memory state is unchanged"))
    {
        return false;
    }

    RecoveryMarkerState restored{};
    if (!Require(
               TryLoadRecoveryMarkerState(context.recovery_marker_file, restored) &&
                   restored.dirty &&
                   restored.last_commit_xid == context.runtime_last_commit_xid,
        "Recreated marker should preserve the unchanged dirty checkpoint state"))
    {
        return false;
    }

    {
        std::ofstream corrupt(context.recovery_marker_file, std::ios::binary | std::ios::trunc);
        corrupt << "dirty=0\nlastCommitXid=37\n";
        if (!Require(corrupt.good(), "Unchanged marker-state test should corrupt the marker contents"))
        {
            return false;
        }
    }
    context.recovery_marker_last_deep_validation_tick_ms = 0;
    if (!Require(
            UpdateRecoveryMarkerBestEffort(&context, true),
            "A due deep validation must repair a corrupted unchanged marker"))
    {
        return false;
    }

    restored = RecoveryMarkerState{};
    return Require(
               TryLoadRecoveryMarkerState(context.recovery_marker_file, restored) &&
                   restored.dirty &&
                   restored.last_commit_xid == context.runtime_last_commit_xid,
        "Deep marker validation should restore the requested dirty state");
#else
    return true;
#endif
}

