bool TestBlockedRecoveryEvidenceSurvivesStaleClearAndShutdownGate()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = (std::filesystem::temp_directory_path() / L"ApfsAccessRecoveryMarkerTests") /
        (L"blocked-evidence-shutdown-" + std::to_wstring(GetCurrentProcessId()) + L"-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "Blocked recovery-evidence test should create its D-drive scratch root"))
    {
        return false;
    }
    ScopeExit cleanup{[&]() { std::filesystem::remove_all(run_root, ec); }};

    const auto read_marker_bytes = [](const std::filesystem::path& path) -> std::string
    {
        std::ifstream input(path, std::ios::binary);
        return std::string(
            std::istreambuf_iterator<char>(input),
            std::istreambuf_iterator<char>());
    };

    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_recovery_policy = L"FailClosed";
    context.native_write_enabled = true;
    context.recovery_marker_file = run_root / "recovery.marker";
    {
        std::ofstream malformed(context.recovery_marker_file, std::ios::binary | std::ios::trunc);
        malformed << "dirty=1\nlastCommitXid=47\nunknown=1\n";
        if (!Require(malformed.good(), "Blocked recovery-evidence test should persist invalid marker bytes"))
        {
            return false;
        }
    }

    const auto startup = LoadRecoveryMarkerAtStartup(context);
    const auto marker_bytes_before = read_marker_bytes(context.recovery_marker_file);
    const auto reason_before = context.runtime_recovery_reason;
    const auto action_before = context.runtime_last_recovery_action;
    const auto stale_clear_result = ClearStaleNativeDirtyMarkerIfClean(&context);
    const auto marker_bytes_after = read_marker_bytes(context.recovery_marker_file);
    RecoveryMarkerState marker_after{};
    const auto marker_status_after = LoadRecoveryMarkerState(
        context.recovery_marker_file,
        marker_after);

    MountContext identity_blocked{};
    identity_blocked.args.readwrite = true;
    identity_blocked.recovery_identity_blocked = true;
    MountContext marker_blocked{};
    marker_blocked.args.readwrite = true;
    marker_blocked.recovery_marker_blocked = true;
    MountContext clean{};
    clean.args.readwrite = true;

    bool ok = true;
    ok &= Require(startup.load_status == RecoveryMarkerLoadStatus::Invalid,
        "Blocked recovery-evidence test should begin from invalid marker evidence");
    ok &= Require(!stale_clear_result,
        "Stale marker clearing must refuse blocked recovery evidence");
    ok &= Require(marker_bytes_after == marker_bytes_before,
        "Stale marker clearing must preserve invalid marker bytes exactly");
    ok &= Require(marker_status_after == RecoveryMarkerLoadStatus::Invalid,
        "Stale marker clearing must preserve invalid marker load status");
    ok &= Require(context.recovery_marker_blocked &&
                      context.pending_native_writes &&
                      context.recovery_active &&
                      context.write_degraded &&
                      !context.native_write_enabled &&
                      !context.overlay_write_enabled &&
                      context.runtime_recovery_reason == reason_before &&
                      context.runtime_last_recovery_action == action_before &&
                      context.runtime_recovery_reason == L"RecoveryMarkerInvalid",
        "Stale marker clearing must preserve RecoveryMarkerInvalid degraded state");
    ok &= Require(!ShouldRunNativeShutdownFinalDrain(identity_blocked),
        "Shutdown final drain must skip identity-blocked recovery evidence");
    ok &= Require(!ShouldRunNativeShutdownFinalDrain(marker_blocked),
        "Shutdown final drain must skip marker-blocked recovery evidence");
    ok &= Require(ShouldRunNativeShutdownFinalDrain(clean),
        "Shutdown final drain should remain enabled for an unblocked read-write mount");
    return ok;
#else
    return true;
#endif
}

