bool TestRecoveryMarkerArmCannotRaceCleanCommitBoundary()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = (std::filesystem::temp_directory_path() / L"ApfsAccessRecoveryMarkerTests") /
        (L"arm-stage-race-" + std::to_wstring(GetCurrentProcessId()) + L"-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "Marker arm/stage race test should create its D-drive scratch root"))
    {
        return false;
    }
    ScopeExit cleanup{[&]() { std::filesystem::remove_all(run_root, ec); }};

    const auto image_path = run_root / "arm-stage-race.apfs.img";
    if (!Require(CreateSyntheticApfsContainerForTest(image_path),
            "Marker arm/stage race test should create its synthetic APFS image"))
    {
        return false;
    }

    MountContext context{};
    context.args.device = image_path.wstring();
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_recovery_policy = L"FailClosed";
    context.args.write_max_dirty_transactions = 128;
    context.args.allow_legacy_scaffold_for_fixtures = true;
    context.args.write_require_canonical_commit = false;
    context.args.write_disallow_scaffold_commit_on_non_fixture = false;
    context.args.write_reject_scaffold_replay_blob_on_non_fixture = false;
    context.args.write_require_canonical_replay_candidate_on_non_fixture = false;
    context.native_write_enabled = true;
    context.recovery_marker_file = run_root / "recovery.marker";

    apfsaccess::rw::MetadataStore::VolumeContext rw_context{};
    rw_context.device_path = image_path.wstring();
    rw_context.volume_name = L"MarkerRace";
    rw_context.allow_legacy_scaffold_for_fixtures = true;
    rw_context.disallow_scaffold_commit_on_non_fixture = false;
    rw_context.reject_scaffold_replay_blob_on_non_fixture = false;
    rw_context.require_canonical_replay_candidate_on_non_fixture = false;
    context.metadata_store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));
    if (!Require(context.metadata_store->LoadContainerSuperblocks(),
            "Marker arm/stage race test should load container superblocks") ||
        !Require(context.metadata_store->LoadObjectMap(),
            "Marker arm/stage race test should load the object map") ||
        !Require(context.metadata_store->LoadSpacemanState(),
            "Marker arm/stage race test should load spaceman state") ||
        !Require(context.metadata_store->PrepareNativeWritePath(),
            "Marker arm/stage race test should prepare the native writer"))
    {
        return false;
    }

    std::atomic<bool> drain_commit_started{false};
    context.metadata_store->SetCommitStageHook([&](std::string_view) -> bool
    {
        drain_commit_started.store(true, std::memory_order_release);
        return true;
    });

    {
        MutationCallbackScope seed_scope(&context);
        if (!Require(RecordNativeMutationBestEffort(
                &context,
                apfsaccess::rw::MetadataStore::MutationOperation::CreateFile,
                L"\\arm-stage-seed.bin"),
                "Marker arm/stage race test should seed one pending mutation"))
        {
            return false;
        }
    }
    context.close_commit_deferred.store(true, std::memory_order_release);

    context.test_pause_after_recovery_marker_arm.store(true, std::memory_order_release);
    auto stage_future = std::async(std::launch::async, [&]()
    {
        MutationCallbackScope mutation_scope(&context);
        return RecordNativeMutationBestEffort(
            &context,
            apfsaccess::rw::MetadataStore::MutationOperation::CreateFile,
            L"\\arm-stage-race.bin");
    });
    const auto pause_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(5);
    while (!context.test_recovery_marker_arm_paused.load(std::memory_order_acquire) &&
           std::chrono::steady_clock::now() < pause_deadline)
    {
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
    }
    if (!Require(context.test_recovery_marker_arm_paused.load(std::memory_order_acquire),
            "Foreground staging should pause after durably arming the marker"))
    {
        context.test_release_recovery_marker_arm.store(true, std::memory_order_release);
        (void)stage_future.get();
        return false;
    }

    OpenContext payload_open{};
    payload_open.allow_write_data = true;
    auto drain_future = std::async(std::launch::async, [&]()
    {
        return DrainDeferredNativeMutationsBeforePayloadOpen(&context, &payload_open);
    });
    const auto drain_start_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while (!drain_commit_started.load(std::memory_order_acquire) &&
           drain_future.wait_for(std::chrono::milliseconds(0)) != std::future_status::ready &&
           std::chrono::steady_clock::now() < drain_start_deadline)
    {
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
    }
    const auto drain_crossed_arm_stage_window =
        drain_commit_started.load(std::memory_order_acquire);
    context.test_release_recovery_marker_arm.store(true, std::memory_order_release);

    const auto staged = stage_future.get();
    const auto drain_status = drain_future.get();
    RecoveryMarkerState marker{};
    const auto marker_loaded = TryLoadRecoveryMarkerState(context.recovery_marker_file, marker);
    const auto pending_mutation_count = context.metadata_store->PendingMutationCount();
    if (drain_crossed_arm_stage_window)
    {
        const auto inconsistent_state = staged &&
            NT_SUCCESS(drain_status) &&
            pending_mutation_count == 1 &&
            marker_loaded &&
            !marker.dirty;
        if (!inconsistent_state)
        {
            std::cerr << "[DIAG] crossed payload-open drain: staged=" << staged
                      << ", status=0x" << std::hex << static_cast<unsigned long>(drain_status) << std::dec
                      << ", pending=" << pending_mutation_count
                      << ", markerLoaded=" << marker_loaded
                      << ", markerDirty=" << marker.dirty
                      << std::endl;
        }
        return Require(inconsistent_state,
                   "Crossing payload-open drain should reproduce staged metadata with a clean marker") &&
               Require(false,
                   "Payload-open drain crossed the active mutation callback marker arm/stage window");
    }

    return Require(staged, "Foreground mutation should stage after the race gate is released") &&
           Require(NT_SUCCESS(drain_status), "The waiting payload-open drain should commit staged metadata") &&
           Require(pending_mutation_count == 0,
               "The waiting payload-open drain should leave no staged metadata") &&
           Require(context.metadata_store->LookupCommittedInodeByPath(L"\\arm-stage-seed.bin").has_value(),
               "The waiting payload-open drain should commit the seeded file") &&
           Require(context.metadata_store->LookupCommittedInodeByPath(L"\\arm-stage-race.bin").has_value(),
               "The waiting payload-open drain should commit the paused mutation") &&
           Require(marker_loaded && !marker.dirty,
               "The marker may become clean only after both staged mutations commit") &&
           Require(!drain_crossed_arm_stage_window,
               "The payload-open drain must wait for the active mutation callback");
#else
    return true;
#endif
}

bool TestAcceptedWriteReplayCommitsAndConvergesWatermarks()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"accepted-replay-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (ec)
    {
        return Require(false, "Accepted replay test should create temp directory");
    }
    ScopeExit cleanup{[&]() { std::filesystem::remove_all(run_root, ec); }};
    const auto image_path = run_root / "accepted-replay.apfs.img";
    if (!Require(CreateSyntheticApfsContainerForTest(image_path), "Accepted replay test should create synthetic APFS image"))
    {
        return false;
    }

    const auto make_store = [&]()
    {
        apfsaccess::rw::MetadataStore::VolumeContext rw_context{
            image_path.wstring(),
            L"Main",
        };
        rw_context.allow_legacy_scaffold_for_fixtures = true;
        rw_context.disallow_scaffold_commit_on_non_fixture = false;
        rw_context.reject_scaffold_replay_blob_on_non_fixture = false;
        rw_context.require_canonical_replay_candidate_on_non_fixture = false;
        auto store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));
        if (!store->LoadContainerSuperblocks() ||
            !store->LoadObjectMap() ||
            !store->LoadSpacemanState() ||
            !store->PrepareNativeWritePath())
        {
            return std::unique_ptr<apfsaccess::rw::MetadataStore>{};
        }
        return store;
    };

    apfsaccess::rw::MetadataStore::PayloadIdentity identity{};
    apfsaccess::rw::MetadataStore::PayloadIdentity second_identity{};
    {
        auto original_store = make_store();
        if (!Require(original_store != nullptr, "Accepted replay source should prepare metadata store"))
        {
            return false;
        }
        apfsaccess::rw::MetadataStore::MutationRequest create{};
        create.operation = apfsaccess::rw::MetadataStore::MutationOperation::CreateFile;
        create.path = L"\\replayed.bin";
        apfsaccess::rw::MetadataStore::MutationRequest write{};
        write.operation = apfsaccess::rw::MetadataStore::MutationOperation::Write;
        write.path = create.path;
        write.length = 4;
        if (!Require(original_store->StageMutation(create) == apfsaccess::rw::MetadataStore::MutationStatus::Applied, "Accepted replay source should stage create") ||
            !Require(original_store->StageMutation(write, &identity) == apfsaccess::rw::MetadataStore::MutationStatus::Applied, "Accepted replay source should stage write identity"))
        {
            return false;
        }

        apfsaccess::rw::MetadataStore::MutationRequest second_create{};
        second_create.operation = apfsaccess::rw::MetadataStore::MutationOperation::CreateFile;
        second_create.path = L"\\replayed-second.bin";
        apfsaccess::rw::MetadataStore::MutationRequest second_write{};
        second_write.operation = apfsaccess::rw::MetadataStore::MutationOperation::Write;
        second_write.path = second_create.path;
        second_write.length = 5;
        if (!Require(
                original_store->StageMutation(second_create) == apfsaccess::rw::MetadataStore::MutationStatus::Applied,
                "Accepted replay source should stage the second create") ||
            !Require(
                original_store->StageMutation(second_write, &second_identity) == apfsaccess::rw::MetadataStore::MutationStatus::Applied,
                "Accepted replay source should stage the second write identity"))
        {
            return false;
        }
    }

    const std::string volume_identity = "accepted-replay-volume";
    const auto spool_root = run_root / "spool";
    const auto wal_path = spool_root / "write-ahead.wal";
    const std::array<std::byte, 4> payload{
        std::byte{'R'}, std::byte{'P'}, std::byte{'L'}, std::byte{'Y'},
    };
    const std::array<std::byte, 5> second_payload{
        std::byte{'B'}, std::byte{'A'}, std::byte{'T'}, std::byte{'C'}, std::byte{'H'},
    };
    std::uint64_t accepted_sequence = 0;
    {
        apfsaccess::rw::PayloadSpool spool({spool_root, volume_identity, 1024 * 1024});
        apfsaccess::rw::TransactionManager tx(L"DeferredContent");
        tx.SetVolumeIdentity(L"accepted-replay-volume");
        tx.SetJournalPath(wal_path.wstring());
        apfsaccess::rw::TransactionManager::MutationIntent create{};
        create.kind = apfsaccess::rw::TransactionManager::MutationKind::CreateFile;
        create.path = L"\\replayed.bin";
        create.object_id = identity.object_id;
        create.generation = identity.generation;
        if (!Require(tx.Begin(), "Accepted replay WAL transaction should begin") ||
            !Require(tx.RecordMutation(create), "Accepted replay WAL should record create"))
        {
            return false;
        }

        apfsaccess::rw::PayloadSpool::AppendResult appended{};
        const auto write_sequence = tx.NextMutationSequence();
        if (!Require(
                spool.Append({
                    volume_identity,
                    identity.object_id,
                    identity.generation,
                    0,
                    write_sequence,
                    std::span<const std::byte>(payload.data(), payload.size()),
                }, &appended),
                "Accepted replay should stage payload"))
        {
            return false;
        }
        apfsaccess::rw::TransactionManager::MutationIntent write{};
        write.kind = apfsaccess::rw::TransactionManager::MutationKind::Write;
        write.path = L"\\replayed.bin";
        write.length = payload.size();
        write.wal_sequence = write_sequence;
        write.object_id = appended.object_id;
        write.generation = appended.generation;
        write.payload_spool_offset = appended.spool_offset;
        write.payload_length = appended.payload_length;
        write.payload_checksum = appended.payload_sha256;
        apfsaccess::rw::TransactionManager::MutationIntent basic_info{};
        basic_info.kind = apfsaccess::rw::TransactionManager::MutationKind::SetBasicInfo;
        basic_info.path = L"\\replayed.bin";
        basic_info.timestamp_utc = 0x01DABEEF;
        basic_info.object_id = identity.object_id;
        basic_info.generation = identity.generation;
        if (!Require(tx.RecordMutation(write), "Accepted replay WAL should record payload reference") ||
            !Require(tx.RecordMutation(basic_info), "Accepted replay WAL should record timestamp") ||
            !Require(spool.FlushPayloadBytes(), "Accepted replay payload bytes should become durable before acceptance") ||
            !Require(tx.Accept(), "Accepted replay WAL should publish acceptance"))
        {
            return false;
        }
        accepted_sequence = tx.Watermarks().accepted_sequence;

        if (!Require(tx.Begin(), "Second accepted replay WAL transaction should begin"))
        {
            return false;
        }
        apfsaccess::rw::TransactionManager::MutationIntent second_create{};
        second_create.kind = apfsaccess::rw::TransactionManager::MutationKind::CreateFile;
        second_create.path = L"\\replayed-second.bin";
        second_create.object_id = second_identity.object_id;
        second_create.generation = second_identity.generation;
        if (!Require(tx.RecordMutation(second_create), "Second accepted replay WAL should record create"))
        {
            return false;
        }

        apfsaccess::rw::PayloadSpool::AppendResult second_appended{};
        const auto second_write_sequence = tx.NextMutationSequence();
        if (!Require(
                spool.Append({
                    volume_identity,
                    second_identity.object_id,
                    second_identity.generation,
                    0,
                    second_write_sequence,
                    std::span<const std::byte>(second_payload.data(), second_payload.size()),
                }, &second_appended),
                "Second accepted replay should stage payload"))
        {
            return false;
        }
        apfsaccess::rw::TransactionManager::MutationIntent second_write{};
        second_write.kind = apfsaccess::rw::TransactionManager::MutationKind::Write;
        second_write.path = L"\\replayed-second.bin";
        second_write.length = second_payload.size();
        second_write.wal_sequence = second_write_sequence;
        second_write.object_id = second_appended.object_id;
        second_write.generation = second_appended.generation;
        second_write.payload_spool_offset = second_appended.spool_offset;
        second_write.payload_length = second_appended.payload_length;
        second_write.payload_checksum = second_appended.payload_sha256;
        if (!Require(tx.RecordMutation(second_write), "Second accepted replay WAL should record payload reference") ||
            !Require(spool.FlushPayloadBytes(), "Second accepted replay payload bytes should become durable before acceptance") ||
            !Require(tx.Accept(), "Second accepted replay WAL should publish acceptance"))
        {
            return false;
        }
        accepted_sequence = tx.Watermarks().accepted_sequence;
    }
    if (!Require(
            !std::filesystem::exists(spool_root / "payload-spool.idx"),
            "Accepted replay restart should begin with a missing advisory spool index"))
    {
        return false;
    }
    {
        std::ofstream torn_tail(wal_path, std::ios::binary | std::ios::app);
        const std::array<char, 5> incomplete_record{'W', 'A', 'L', '!', '\0'};
        torn_tail.write(incomplete_record.data(), static_cast<std::streamsize>(incomplete_record.size()));
    }

    MountContext context{};
    context.args.device = image_path.wstring();
    context.args.write_require_canonical_commit = false;
    context.args.write_disallow_scaffold_commit_on_non_fixture = false;
    context.args.write_reject_scaffold_replay_blob_on_non_fixture = false;
    context.args.write_require_canonical_replay_candidate_on_non_fixture = false;
    context.native_write_enabled = true;
    context.payload_spool_volume_identity = volume_identity;
    context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{spool_root, volume_identity, 1024 * 1024});
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"DeferredContent");
    context.tx_manager->SetVolumeIdentity(L"accepted-replay-volume");
    context.tx_manager->SetJournalPath(wal_path.wstring());
    context.metadata_store = make_store();
    if (!Require(context.metadata_store != nullptr, "Accepted replay target should prepare metadata store"))
    {
        return false;
    }
    const auto replay_start_xid = context.metadata_store->CheckpointXid();
    if (!ReplayAcceptedWriteAheadLogAfterMetadataBootstrap(context))
    {
        const auto watermarks = context.tx_manager->Watermarks();
        std::wcerr << L"[DIAG] accepted replay reason=" << context.runtime_recovery_reason
            << L", metadataMutation=" << context.metadata_store->LastMutationFailureReason()
            << L", metadataCommit=" << context.metadata_store->LastCommitFailureReason()
            << L", metadataRecovery=" << context.metadata_store->RecoveryReason()
            << L", object=" << identity.object_id
            << L", generation=" << identity.generation
            << L", accepted=" << watermarks.accepted_sequence
            << L", durable=" << watermarks.apfs_durable_sequence
            << L", cleanup=" << watermarks.cleanup_sequence
            << std::endl;
        return Require(false, "Accepted WAL/spool transaction should replay");
    }

    const auto watermarks = context.tx_manager->Watermarks();
    const auto inode = context.metadata_store->LookupCommittedInodeByPath(L"\\replayed.bin");
    const auto second_inode = context.metadata_store->LookupCommittedInodeByPath(L"\\replayed-second.bin");
    std::vector<std::byte> committed;
    std::vector<std::byte> second_committed;
    const auto replay_end_xid = context.metadata_store->CheckpointXid();
    if (!Require(watermarks.accepted_sequence == accepted_sequence, "Replay should preserve accepted watermark") ||
        !Require(watermarks.apfs_durable_sequence == accepted_sequence, "Replay should advance APFS-durable watermark") ||
        !Require(watermarks.cleanup_sequence == accepted_sequence, "Replay should advance cleanup watermark") ||
        !Require(
            replay_start_xid.has_value() &&
                replay_end_xid.has_value() &&
                replay_end_xid.value() == replay_start_xid.value() + 1,
            "Multiple accepted transactions should share one APFS checkpoint") ||
        !Require(context.payload_spool->SnapshotCounters().dirty_range_count == 0, "Replay should clean durable spool ranges") ||
        !Require(inode.has_value() && inode->timestamp_utc == 0x01DABEEF, "Replay should restore file and timestamp") ||
        !Require(context.metadata_store->ReadCommittedFileRange(L"\\replayed.bin", 0, payload.size(), committed), "Replay should read committed payload") ||
        !Require(committed == std::vector<std::byte>(payload.begin(), payload.end()), "Replay should preserve payload bytes exactly") ||
        !Require(second_inode.has_value() && !second_inode->is_directory, "Replay should restore the second accepted file") ||
        !Require(context.metadata_store->ReadCommittedFileRange(L"\\replayed-second.bin", 0, second_payload.size(), second_committed), "Replay should read the second committed payload") ||
        !Require(second_committed == std::vector<std::byte>(second_payload.begin(), second_payload.end()), "Replay should preserve the second payload bytes exactly"))
    {
        return false;
    }

    const auto persist_applied_batch = [&](
        const std::filesystem::path& root,
        bool corrupt_sha,
        bool omit_spool_range = false,
        bool omit_create = false,
        std::uint64_t generation_override = 0)
    {
        auto spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
            apfsaccess::rw::PayloadSpool::Options{root, volume_identity, 1024 * 1024});
        auto tx = std::make_unique<apfsaccess::rw::TransactionManager>(L"DeferredContent");
        tx->SetVolumeIdentity(L"accepted-replay-volume");
        tx->SetJournalPath((root / "write-ahead.wal").wstring());
        apfsaccess::rw::TransactionManager::MutationIntent create{};
        create.kind = apfsaccess::rw::TransactionManager::MutationKind::CreateFile;
        create.path = L"\\replayed.bin";
        create.object_id = identity.object_id;
        create.generation = identity.generation;
        if (!tx->Begin() || ((!corrupt_sha && !omit_create) && !tx->RecordMutation(create)))
        {
            return std::pair{
                std::unique_ptr<apfsaccess::rw::PayloadSpool>{},
                std::unique_ptr<apfsaccess::rw::TransactionManager>{}};
        }
        apfsaccess::rw::PayloadSpool::AppendResult appended{};
        const auto write_sequence = tx->NextMutationSequence();
        const auto payload_identity = generation_override == 0
            ? identity
            : apfsaccess::rw::MetadataStore::PayloadIdentity{ identity.object_id, generation_override };
        if (!spool->Append({
                volume_identity,
                payload_identity.object_id,
                payload_identity.generation,
                0,
                write_sequence,
                std::span<const std::byte>(payload.data(), payload.size()),
            }, &appended))
        {
            return std::pair{
                std::unique_ptr<apfsaccess::rw::PayloadSpool>{},
                std::unique_ptr<apfsaccess::rw::TransactionManager>{}};
        }
        apfsaccess::rw::TransactionManager::MutationIntent write{};
        write.kind = apfsaccess::rw::TransactionManager::MutationKind::Write;
        write.path = L"\\replayed.bin";
        write.length = appended.payload_length;
        write.wal_sequence = write_sequence;
        write.object_id = appended.object_id;
        write.generation = appended.generation;
        write.payload_spool_offset = appended.spool_offset;
        write.payload_length = appended.payload_length;
        write.payload_checksum = appended.payload_sha256;
        if (corrupt_sha)
        {
            write.payload_checksum[0] ^= 0xff;
        }
        apfsaccess::rw::TransactionManager::MutationIntent basic_info{};
        basic_info.kind = apfsaccess::rw::TransactionManager::MutationKind::SetBasicInfo;
        basic_info.path = L"\\replayed.bin";
        basic_info.timestamp_utc = 0x01DABEEF;
        basic_info.object_id = payload_identity.object_id;
        basic_info.generation = payload_identity.generation;
        if (!tx->RecordMutation(write) ||
            !tx->RecordMutation(basic_info) ||
            !spool->FlushDirtyState() ||
            !tx->Accept())
        {
            return std::pair{
                std::unique_ptr<apfsaccess::rw::PayloadSpool>{},
                std::unique_ptr<apfsaccess::rw::TransactionManager>{}};
        }
        if (omit_spool_range && !spool->DiscardSequence(write_sequence))
        {
            return std::pair{
                std::unique_ptr<apfsaccess::rw::PayloadSpool>{},
                std::unique_ptr<apfsaccess::rw::TransactionManager>{}};
        }
        return std::pair{std::move(spool), std::move(tx)};
    };

    const auto committed_xid = context.metadata_store->LastCommittedXid();
    context.payload_spool.reset();
    context.tx_manager.reset();
    auto [mismatched_generation_spool, mismatched_generation_tx] = persist_applied_batch(
        run_root / "mismatched-generation",
        false,
        false,
        true,
        identity.generation + 2);
    if (!Require(
            mismatched_generation_spool != nullptr && mismatched_generation_tx != nullptr,
            "Mismatched-generation replay fixture should persist"))
    {
        return false;
    }
    context.payload_spool = std::move(mismatched_generation_spool);
    context.tx_manager = std::move(mismatched_generation_tx);
    const auto mismatched_generation_accepted = context.tx_manager->Watermarks().accepted_sequence;
    if (!Require(
            !ReplayAcceptedWriteAheadLogAfterMetadataBootstrap(context),
            "Replay must reject a matching object/path with a mismatched generation") ||
        !Require(
            context.runtime_recovery_reason == L"AcceptedWriteReplayIdentityMismatch",
            "Mismatched generation should report an identity mismatch") ||
        !Require(
            context.tx_manager->Watermarks().apfs_durable_sequence < mismatched_generation_accepted,
            "Mismatched generation must not advance APFS durability"))
    {
        return false;
    }

    context.payload_spool.reset();
    context.tx_manager.reset();
    auto [applied_spool, applied_tx] = persist_applied_batch(run_root / "already-applied", false, false, true);
    context.payload_spool = std::move(applied_spool);
    context.tx_manager = std::move(applied_tx);
    if (!Require(ReplayAcceptedWriteAheadLogAfterMetadataBootstrap(context), "Already-applied accepted transaction should converge without replaying a checkpoint") ||
        !Require(context.metadata_store->LastCommittedXid() == committed_xid, "Already-applied replay should not create a duplicate APFS checkpoint"))
    {
        return false;
    }

    context.payload_spool.reset();
    context.tx_manager.reset();
    auto [cleanup_spool, cleanup_tx] = persist_applied_batch(run_root / "cleanup-only", false);
    if (!Require(cleanup_spool != nullptr && cleanup_tx != nullptr, "Cleanup-only replay fixture should persist"))
    {
        return false;
    }
    const auto cleanup_accepted = cleanup_tx->Watermarks().accepted_sequence;
    const auto cleanup_xid = context.metadata_store->LastCommittedXid();
    if (!Require(
            cleanup_tx->MarkApfsDurableThrough(cleanup_accepted),
            "Cleanup-only fixture should persist the APFS-durable watermark") ||
        !Require(
            cleanup_spool->CleanupThroughSequence(cleanup_accepted),
            "Cleanup-only fixture should allow the payload cleanup boundary"))
    {
        return false;
    }
    cleanup_spool.reset();
    cleanup_tx.reset();
    const auto cleanup_root = run_root / "cleanup-only";
    context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{cleanup_root, volume_identity, 1024 * 1024});
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"DeferredContent");
    context.tx_manager->SetVolumeIdentity(L"accepted-replay-volume");
    context.tx_manager->SetJournalPath((cleanup_root / "write-ahead.wal").wstring());
    if (!Require(
            ReplayAcceptedWriteAheadLogAfterMetadataBootstrap(context),
            "Restart after spool cleanup but before cleanup watermark should converge") ||
        !Require(
            context.metadata_store->LastCommittedXid() == cleanup_xid,
            "Cleanup-only restart should not create a duplicate APFS checkpoint") ||
        !Require(
            context.tx_manager->Watermarks().cleanup_sequence == cleanup_accepted,
            "Cleanup-only restart should publish the cleanup watermark"))
    {
        return false;
    }

    context.payload_spool.reset();
    context.tx_manager.reset();
    const auto durable_prefix_root = run_root / "durable-prefix-spool-rebuild";
    const auto durable_prefix_wal_path = durable_prefix_root / "write-ahead.wal";
    const auto durable_prefix_spool_path = durable_prefix_root / "payload-spool.bin";
    const auto durable_prefix_index_path = durable_prefix_root / "payload-spool.idx";
    const auto durable_prefix_first_inode =
        context.metadata_store->LookupCommittedInodeByPath(L"\\replayed.bin");
    const auto durable_prefix_second_inode =
        context.metadata_store->LookupCommittedInodeByPath(L"\\replayed-second.bin");
    const auto durable_prefix_checkpoint_xid = context.metadata_store->CheckpointXid();
    if (!Require(
            durable_prefix_first_inode.has_value() &&
                durable_prefix_second_inode.has_value() &&
                durable_prefix_checkpoint_xid.has_value() &&
                *durable_prefix_checkpoint_xid != (std::numeric_limits<std::uint64_t>::max)(),
            "Durable-prefix rebuild fixture should resolve committed payload identities"))
    {
        return false;
    }

    const std::array<std::byte, 5> durable_prefix_replay_payload{
        std::byte{'N'}, std::byte{'E'}, std::byte{'X'}, std::byte{'T'}, std::byte{'!'},
    };
    apfsaccess::rw::PayloadSpool::AppendResult durable_prefix_cleaned_range{};
    std::uint64_t durable_prefix_first_accepted = 0;
    std::uint64_t durable_prefix_last_accepted = 0;
    {
        apfsaccess::rw::PayloadSpool spool(
            {durable_prefix_root, volume_identity, 1024 * 1024});
        apfsaccess::rw::TransactionManager tx(L"DeferredContent");
        tx.SetVolumeIdentity(L"accepted-replay-volume");
        tx.SetJournalPath(durable_prefix_wal_path.wstring());

        const auto accept_write = [&](
            const std::wstring& path,
            std::uint64_t object_id,
            std::uint64_t generation,
            std::span<const std::byte> bytes,
            apfsaccess::rw::PayloadSpool::AppendResult& appended)
        {
            if (!tx.Begin())
            {
                return false;
            }
            const auto write_sequence = tx.NextMutationSequence();
            if (!spool.Append({
                    volume_identity,
                    object_id,
                    generation,
                    0,
                    write_sequence,
                    bytes,
                }, &appended))
            {
                return false;
            }

            apfsaccess::rw::TransactionManager::MutationIntent write{};
            write.kind = apfsaccess::rw::TransactionManager::MutationKind::Write;
            write.path = path;
            write.length = appended.payload_length;
            write.wal_sequence = write_sequence;
            write.object_id = appended.object_id;
            write.generation = appended.generation;
            write.payload_spool_offset = appended.spool_offset;
            write.payload_length = appended.payload_length;
            write.payload_checksum = appended.payload_sha256;
            return tx.RecordMutation(write) &&
                   spool.FlushPayloadBytes() &&
                   tx.Accept();
        };

        const auto first_generation = durable_prefix_first_inode->xid == 0
            ? durable_prefix_first_inode->object_id
            : durable_prefix_first_inode->xid;
        if (!Require(
                accept_write(
                    L"\\replayed.bin",
                    durable_prefix_first_inode->object_id,
                    first_generation,
                    std::span<const std::byte>(payload.data(), payload.size()),
                    durable_prefix_cleaned_range),
                "Durable-prefix rebuild fixture should accept the already-applied write"))
        {
            return false;
        }
        durable_prefix_first_accepted = tx.Watermarks().accepted_sequence;

        apfsaccess::rw::PayloadSpool::AppendResult durable_prefix_live_range{};
        if (!Require(
                accept_write(
                    L"\\replayed-second.bin",
                    durable_prefix_second_inode->object_id,
                    *durable_prefix_checkpoint_xid + 1,
                    std::span<const std::byte>(
                        durable_prefix_replay_payload.data(),
                        durable_prefix_replay_payload.size()),
                    durable_prefix_live_range),
                "Durable-prefix rebuild fixture should accept the later unapplied write"))
        {
            return false;
        }
        durable_prefix_last_accepted = tx.Watermarks().accepted_sequence;
        if (!Require(
                tx.MarkApfsDurableThrough(durable_prefix_first_accepted),
                "Durable-prefix rebuild fixture should persist the first APFS-durable boundary") ||
            !Require(
                spool.CleanupThroughSequence(durable_prefix_first_accepted),
                "Durable-prefix rebuild fixture should clean the first payload range") ||
            !Require(
                tx.Watermarks().cleanup_sequence < durable_prefix_first_accepted,
                "Durable-prefix rebuild fixture should retain the stale cleanup watermark"))
        {
            return false;
        }
    }

    {
        std::fstream cleaned_payload(
            durable_prefix_spool_path,
            std::ios::binary | std::ios::in | std::ios::out);
        std::vector<char> cleared_bytes(
            static_cast<std::size_t>(durable_prefix_cleaned_range.payload_length),
            '\0');
        cleaned_payload.seekp(
            static_cast<std::streamoff>(durable_prefix_cleaned_range.spool_offset),
            std::ios::beg);
        cleaned_payload.write(
            cleared_bytes.data(),
            static_cast<std::streamsize>(cleared_bytes.size()));
        cleaned_payload.flush();
        if (!Require(
                cleaned_payload.good(),
                "Durable-prefix rebuild fixture should make the cleaned payload bytes unavailable"))
        {
            return false;
        }
    }
    ec.clear();
    const auto removed_durable_prefix_index =
        std::filesystem::remove(durable_prefix_index_path, ec);
    if (!Require(
            !ec && removed_durable_prefix_index,
            "Durable-prefix rebuild fixture should remove the advisory spool index"))
    {
        return false;
    }

    context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{
            durable_prefix_root,
            volume_identity,
            1024 * 1024});
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"DeferredContent");
    context.tx_manager->SetVolumeIdentity(L"accepted-replay-volume");
    context.tx_manager->SetJournalPath(durable_prefix_wal_path.wstring());
    const auto durable_prefix_replay_start_xid = context.metadata_store->CheckpointXid();
    if (!Require(
            context.payload_spool->RecoveryRequired(),
            "Durable-prefix restart should require advisory spool-index reconstruction") ||
        !Require(
            ReplayAcceptedWriteAheadLogAfterMetadataBootstrap(context),
            "Spool rebuild should ignore cleaned APFS-durable payloads and replay later accepted work"))
    {
        return false;
    }

    const auto durable_prefix_watermarks = context.tx_manager->Watermarks();
    const auto durable_prefix_replay_end_xid = context.metadata_store->CheckpointXid();
    std::vector<std::byte> durable_prefix_committed;
    if (!Require(
            durable_prefix_watermarks.accepted_sequence == durable_prefix_last_accepted &&
                durable_prefix_watermarks.apfs_durable_sequence == durable_prefix_last_accepted &&
                durable_prefix_watermarks.cleanup_sequence == durable_prefix_last_accepted,
            "Durable-prefix replay should converge all watermarks through the later transaction") ||
        !Require(
            durable_prefix_replay_start_xid.has_value() &&
                durable_prefix_replay_end_xid.has_value() &&
                *durable_prefix_replay_end_xid == *durable_prefix_replay_start_xid + 1,
            "Durable-prefix replay should commit only the later accepted transaction") ||
        !Require(
            context.metadata_store->ReadCommittedFileRange(
                L"\\replayed-second.bin",
                0,
                durable_prefix_replay_payload.size(),
                durable_prefix_committed),
            "Durable-prefix replay should read the later committed payload") ||
        !Require(
            durable_prefix_committed == std::vector<std::byte>(
                durable_prefix_replay_payload.begin(),
                durable_prefix_replay_payload.end()),
            "Durable-prefix replay should preserve the later accepted payload exactly"))
    {
        return false;
    }
    const auto post_durable_prefix_committed_xid =
        context.metadata_store->LastCommittedXid();

    context.payload_spool.reset();
    context.tx_manager.reset();
    auto [bad_spool, bad_tx] = persist_applied_batch(run_root / "bad-sha", true);
    if (!Require(bad_spool != nullptr && bad_tx != nullptr, "Checksum-mismatch replay fixture should persist"))
    {
        return false;
    }
    context.payload_spool = std::move(bad_spool);
    context.tx_manager = std::move(bad_tx);
    const auto bad_accepted = context.tx_manager->Watermarks().accepted_sequence;
    if (!Require(!ReplayAcceptedWriteAheadLogAfterMetadataBootstrap(context), "Mismatched WAL payload SHA-256 should fail closed") ||
        !Require(context.runtime_recovery_reason == L"AcceptedWriteReplayPayloadMismatch", "Mismatched payload should report exact replay reason") ||
        !Require(context.tx_manager->Watermarks().apfs_durable_sequence < bad_accepted, "Mismatched payload must not advance APFS durability") ||
        !Require(context.metadata_store->LastCommittedXid() == post_durable_prefix_committed_xid, "Mismatched payload must not issue an APFS checkpoint"))
    {
        return false;
    }

    context.payload_spool.reset();
    context.tx_manager.reset();
    auto [missing_spool, missing_tx] = persist_applied_batch(run_root / "missing-spool", false, true, true);
    if (!Require(missing_spool != nullptr && missing_tx != nullptr, "Missing-spool replay fixture should persist"))
    {
        return false;
    }
    context.payload_spool = std::move(missing_spool);
    context.tx_manager = std::move(missing_tx);
    const auto missing_accepted = context.tx_manager->Watermarks().accepted_sequence;
    const auto missing_replay = ReplayAcceptedWriteAheadLogAfterMetadataBootstrap(context);
    if (!Require(!missing_replay, "Missing accepted spool range should fail closed") ||
        !Require(context.runtime_recovery_reason == L"AcceptedWriteReplayPayloadMismatch", "Missing spool range should report replay payload failure") ||
        !Require(context.tx_manager->Watermarks().apfs_durable_sequence < missing_accepted, "Missing spool range must not advance APFS durability") ||
        !Require(context.metadata_store->LastCommittedXid() == post_durable_prefix_committed_xid, "Missing spool range must not issue an APFS checkpoint"))
    {
        return false;
    }

    context.payload_spool.reset();
    context.tx_manager.reset();
    const auto inline_root = run_root / "inline-truncated-spool";
    const auto inline_wal_path = inline_root / "write-ahead.wal";
    auto inline_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{inline_root, volume_identity, 1024 * 1024});
    auto inline_tx = std::make_unique<apfsaccess::rw::TransactionManager>(L"DeferredContent");
    inline_tx->SetVolumeIdentity(L"accepted-replay-volume");
    inline_tx->SetJournalPath(inline_wal_path.wstring());
    const std::array<std::byte, 8> inline_payload{
        std::byte{0x91}, std::byte{0x82}, std::byte{0x73}, std::byte{0x64},
        std::byte{0x55}, std::byte{0x46}, std::byte{0x37}, std::byte{0x28},
    };
    const auto inline_inode = context.metadata_store->LookupCommittedInodeByPath(L"\\replayed.bin");
    if (!Require(inline_inode.has_value(), "Inline replay fixture should resolve its committed target"))
    {
        return false;
    }
    const auto inline_checkpoint_xid = context.metadata_store->CheckpointXid();
    if (!Require(
            inline_checkpoint_xid.has_value() &&
                *inline_checkpoint_xid != (std::numeric_limits<std::uint64_t>::max)(),
            "Inline replay fixture should resolve its next checkpoint generation"))
    {
        return false;
    }
    const auto inline_generation = *inline_checkpoint_xid + 1;
    apfsaccess::rw::PayloadSpool::AppendResult inline_appended{};
    if (!Require(inline_tx->Begin(), "Inline replay fixture should begin") ||
        !Require(
            inline_spool->Append({
                volume_identity,
                inline_inode->object_id,
                inline_generation,
                0,
                inline_tx->NextMutationSequence(),
                std::span<const std::byte>(inline_payload.data(), inline_payload.size()),
            }, &inline_appended),
            "Inline replay fixture should append redundant spool bytes"))
    {
        return false;
    }
    apfsaccess::rw::TransactionManager::MutationIntent inline_write{};
    inline_write.kind = apfsaccess::rw::TransactionManager::MutationKind::Write;
    inline_write.path = L"\\replayed.bin";
    inline_write.length = inline_payload.size();
    inline_write.wal_sequence = inline_appended.wal_sequence;
    inline_write.object_id = inline_appended.object_id;
    inline_write.generation = inline_appended.generation;
    inline_write.payload_spool_offset = inline_appended.spool_offset;
    inline_write.payload_length = inline_appended.payload_length;
    inline_write.payload_checksum = inline_appended.payload_sha256;
    inline_write.inline_payload.assign(inline_payload.begin(), inline_payload.end());
    if (!Require(inline_tx->RecordMutation(inline_write), "Inline replay fixture should record its WAL payload") ||
        !Require(inline_tx->CanAcceptWithoutPayloadSpoolFlush(), "Inline replay fixture should be self-contained") ||
        !Require(inline_tx->Accept(), "Inline replay fixture should publish acceptance without a spool flush"))
    {
        return false;
    }
    const auto inline_accepted = inline_tx->Watermarks().accepted_sequence;
    inline_spool.reset();
    inline_tx.reset();
    std::filesystem::remove(inline_root / "payload-spool.idx", ec);
    ec.clear();
    std::filesystem::resize_file(inline_root / "payload-spool.bin", 2, ec);
    if (!Require(!ec, "Inline replay fixture should truncate its redundant spool payload"))
    {
        return false;
    }

    context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{inline_root, volume_identity, 1024 * 1024});
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"DeferredContent");
    context.tx_manager->SetVolumeIdentity(L"accepted-replay-volume");
    context.tx_manager->SetJournalPath(inline_wal_path.wstring());
    const auto inline_recovery_required = context.payload_spool->RecoveryRequired();
    const auto inline_replay_result = ReplayAcceptedWriteAheadLogAfterMetadataBootstrap(context);
    if (!inline_replay_result)
    {
        const auto inline_failed_watermarks = context.tx_manager->Watermarks();
        std::wcerr << L"[DIAG] inline replay reason=" << context.runtime_recovery_reason
            << L", mutation=" << context.metadata_store->LastMutationFailureReason()
            << L", commit=" << context.metadata_store->LastCommitFailureReason()
            << L", accepted=" << inline_failed_watermarks.accepted_sequence
            << L", durable=" << inline_failed_watermarks.apfs_durable_sequence
            << L", cleanup=" << inline_failed_watermarks.cleanup_sequence
            << std::endl;
    }
    if (!Require(inline_recovery_required, "Truncated orphan spool bytes should initially require recovery") ||
        !Require(inline_replay_result, "Inline WAL replay should not require durable spool payload bytes"))
    {
        return false;
    }
    std::vector<std::byte> inline_committed;
    const auto inline_watermarks = context.tx_manager->Watermarks();
    return Require(
               context.metadata_store->ReadCommittedFileRange(
                   L"\\replayed.bin",
                   0,
                   inline_payload.size(),
                   inline_committed),
               "Inline replay should expose committed payload bytes") &&
           Require(inline_committed == std::vector<std::byte>(inline_payload.begin(), inline_payload.end()), "Inline replay should preserve byte-identical payload") &&
           Require(inline_watermarks.apfs_durable_sequence == inline_accepted, "Inline replay should advance APFS durability") &&
           Require(inline_watermarks.cleanup_sequence == inline_accepted, "Inline replay should advance cleanup") &&
           Require(!context.payload_spool->RecoveryRequired(), "Inline replay should clear redundant spool recovery state");
#else
    return true;
#endif
}

bool TestAcceptedReplayRecognizesFinalDeleteState()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"accepted-final-delete-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "Accepted final-delete test should create its temp directory"))
    {
        return false;
    }
    ScopeExit cleanup{[&]() { std::filesystem::remove_all(run_root, ec); }};

    const auto image_path = run_root / "accepted-final-delete.apfs.img";
    if (!Require(
            CreateSyntheticApfsContainerForTest(image_path),
            "Accepted final-delete test should create a synthetic APFS image"))
    {
        return false;
    }

    const auto make_store = [&]()
    {
        apfsaccess::rw::MetadataStore::VolumeContext rw_context{
            image_path.wstring(),
            L"Main",
        };
        rw_context.allow_legacy_scaffold_for_fixtures = true;
        rw_context.disallow_scaffold_commit_on_non_fixture = false;
        rw_context.reject_scaffold_replay_blob_on_non_fixture = false;
        rw_context.require_canonical_replay_candidate_on_non_fixture = false;
        auto store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));
        if (!store->LoadContainerSuperblocks() ||
            !store->LoadObjectMap() ||
            !store->LoadSpacemanState() ||
            !store->PrepareNativeWritePath())
        {
            return std::unique_ptr<apfsaccess::rw::MetadataStore>{};
        }
        return store;
    };

    auto source_store = make_store();
    if (!Require(source_store != nullptr, "Accepted final-delete source should prepare metadata"))
    {
        return false;
    }
    apfsaccess::rw::MetadataStore::MutationRequest create{};
    create.operation = apfsaccess::rw::MetadataStore::MutationOperation::CreateFile;
    create.path = L"\\deleted-after-basic-info.bin";
    if (!Require(
            source_store->StageMutation(create) == apfsaccess::rw::MetadataStore::MutationStatus::Applied &&
                source_store->CommitTransaction() == apfsaccess::rw::MetadataStore::CommitStatus::Committed,
            "Accepted final-delete source should persist its initial file"))
    {
        return false;
    }

    apfsaccess::rw::MetadataStore::PayloadIdentity basic_identity{};
    apfsaccess::rw::MetadataStore::PayloadIdentity delete_identity{};
    apfsaccess::rw::MetadataStore::MutationRequest basic_info{};
    basic_info.operation = apfsaccess::rw::MetadataStore::MutationOperation::SetBasicInfo;
    basic_info.path = create.path;
    basic_info.timestamp_utc = 0x01DABEEF;
    apfsaccess::rw::MetadataStore::MutationRequest remove{};
    remove.operation = apfsaccess::rw::MetadataStore::MutationOperation::Delete;
    remove.path = create.path;
    if (!Require(
            source_store->StageMutation(basic_info, &basic_identity) ==
                    apfsaccess::rw::MetadataStore::MutationStatus::Applied &&
                source_store->StageMutation(remove, &delete_identity) ==
                    apfsaccess::rw::MetadataStore::MutationStatus::Applied &&
                basic_identity.object_id != 0 &&
                basic_identity.object_id == delete_identity.object_id &&
                basic_identity.generation == delete_identity.generation,
            "Accepted final-delete source should stage matching timestamp and delete identities"))
    {
        return false;
    }

    constexpr auto volume_identity = "accepted-final-delete-volume";
    const auto spool_root = run_root / "spool";
    const auto wal_path = spool_root / "write-ahead.wal";
    {
        apfsaccess::rw::TransactionManager tx(L"DeferredContent");
        tx.SetVolumeIdentity(L"accepted-final-delete-volume");
        tx.SetJournalPath(wal_path.wstring());
        apfsaccess::rw::TransactionManager::MutationIntent wal_basic{};
        wal_basic.kind = apfsaccess::rw::TransactionManager::MutationKind::SetBasicInfo;
        wal_basic.path = create.path;
        wal_basic.timestamp_utc = basic_info.timestamp_utc;
        wal_basic.object_id = basic_identity.object_id;
        wal_basic.generation = basic_identity.generation;
        apfsaccess::rw::TransactionManager::MutationIntent wal_delete{};
        wal_delete.kind = apfsaccess::rw::TransactionManager::MutationKind::Delete;
        wal_delete.path = create.path;
        wal_delete.object_id = delete_identity.object_id;
        wal_delete.generation = delete_identity.generation;
        if (!Require(
                tx.Begin() &&
                    tx.RecordMutation(wal_basic) &&
                    tx.RecordMutation(wal_delete) &&
                    tx.Accept(),
                "Accepted final-delete source should publish its WAL transaction"))
        {
            return false;
        }
    }
    if (!Require(
            source_store->CommitTransaction() == apfsaccess::rw::MetadataStore::CommitStatus::Committed,
            "Accepted final-delete source should persist the final deleted state"))
    {
        return false;
    }
    source_store.reset();

    MountContext context{};
    context.args.device = image_path.wstring();
    context.args.volume = L"Main";
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_require_canonical_commit = false;
    context.args.write_disallow_scaffold_commit_on_non_fixture = false;
    context.args.write_reject_scaffold_replay_blob_on_non_fixture = false;
    context.args.write_require_canonical_replay_candidate_on_non_fixture = false;
    context.native_write_enabled = true;
    context.payload_spool_volume_identity = volume_identity;
    context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{spool_root, volume_identity, 1024 * 1024});
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"DeferredContent");
    context.tx_manager->SetVolumeIdentity(L"accepted-final-delete-volume");
    context.tx_manager->SetJournalPath(wal_path.wstring());
    context.metadata_store = make_store();
    if (!Require(context.metadata_store != nullptr, "Accepted final-delete target should prepare metadata"))
    {
        return false;
    }

    const auto checkpoint_before_replay = context.metadata_store->CheckpointXid();
    context.runtime_last_commit_xid = checkpoint_before_replay;
    context.recovery_marker_file = run_root / "recovery.marker";
    if (!Require(
            UpdateRecoveryMarkerBestEffort(&context, false),
            "Accepted final-delete target should begin with a clean recovery marker"))
    {
        return false;
    }
    std::ifstream initial_marker_input(context.recovery_marker_file, std::ios::binary);
    const std::string initial_marker_text{
        std::istreambuf_iterator<char>(initial_marker_input),
        std::istreambuf_iterator<char>()};
    initial_marker_input.close();
    if (!Require(
            initial_marker_text.find("dirty=0") != std::string::npos,
            "Accepted final-delete target should persist its initially clean marker") ||
        !Require(
            ArmRecoveryMarkerForPendingWriteAheadLog(context, true),
            "Pending accepted WAL should re-arm the recovery marker before replay"))
    {
        return false;
    }
    ClearRecoveredMarkerIfClean(context, L"PrematureStartupClear");
    std::ifstream dirty_marker_input(context.recovery_marker_file, std::ios::binary);
    const std::string dirty_marker_text{
        std::istreambuf_iterator<char>(dirty_marker_input),
        std::istreambuf_iterator<char>()};
    dirty_marker_input.close();
    if (!Require(
            context.pending_native_writes && dirty_marker_text.find("dirty=1") != std::string::npos,
            "Startup must retain a dirty marker while accepted WAL is ahead of APFS durability"))
    {
        return false;
    }

    const auto accepted_sequence = context.tx_manager->Watermarks().accepted_sequence;
    if (!Require(
            accepted_sequence != 0 && ReplayAcceptedWriteAheadLogAfterMetadataBootstrap(context),
            "Accepted final-delete transaction should converge from its already-applied final state"))
    {
        return false;
    }
    const auto watermarks = context.tx_manager->Watermarks();
    const auto checkpoint_after_replay = context.metadata_store->CheckpointXid();
    std::ifstream clean_marker_input(context.recovery_marker_file, std::ios::binary);
    const std::string clean_marker_text{
        std::istreambuf_iterator<char>(clean_marker_input),
        std::istreambuf_iterator<char>()};
    return Require(
               checkpoint_before_replay == checkpoint_after_replay,
               "Already-applied final delete should not create a duplicate APFS checkpoint") &&
           Require(
               watermarks.apfs_durable_sequence == accepted_sequence &&
                   watermarks.cleanup_sequence == accepted_sequence,
               "Already-applied final delete should converge durability and cleanup watermarks") &&
           Require(
               !context.metadata_store->LookupCommittedInodeByObjectId(delete_identity.object_id).has_value(),
               "Accepted final-delete replay should keep the deleted object absent") &&
           Require(
               !context.pending_native_writes && clean_marker_text.find("dirty=0") != std::string::npos,
               "Accepted final-delete replay should clear the marker only after watermark convergence");
#else
    return true;
#endif
}

bool TestAcceptedReplayDeleteHidesEarlierWriteAcrossBatch()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"accepted-batch-delete-hides-write-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "Accepted batch delete-hides-write test should create its temp directory"))
    {
        return false;
    }
    ScopeExit cleanup{[&]() { std::filesystem::remove_all(run_root, ec); }};

    const auto image_path = run_root / "accepted-batch-delete-hides-write.apfs.img";
    if (!Require(
            CreateSyntheticApfsContainerForTest(image_path),
            "Accepted batch delete-hides-write test should create a synthetic APFS image"))
    {
        return false;
    }

    const auto make_store = [&]()
    {
        apfsaccess::rw::MetadataStore::VolumeContext rw_context{
            image_path.wstring(),
            L"Main",
        };
        rw_context.allow_legacy_scaffold_for_fixtures = true;
        rw_context.disallow_scaffold_commit_on_non_fixture = false;
        rw_context.reject_scaffold_replay_blob_on_non_fixture = false;
        rw_context.require_canonical_replay_candidate_on_non_fixture = false;
        auto store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));
        if (!store->LoadContainerSuperblocks() ||
            !store->LoadObjectMap() ||
            !store->LoadSpacemanState() ||
            !store->PrepareNativeWritePath())
        {
            return std::unique_ptr<apfsaccess::rw::MetadataStore>{};
        }
        return store;
    };

    auto source_store = make_store();
    if (!Require(source_store != nullptr, "Accepted batch delete-hides-write source should prepare metadata"))
    {
        return false;
    }
    apfsaccess::rw::MetadataStore::MutationRequest create{};
    create.operation = apfsaccess::rw::MetadataStore::MutationOperation::CreateFile;
    create.path = L"\\batch-hide.bin";
    if (!Require(
            source_store->StageMutation(create) == apfsaccess::rw::MetadataStore::MutationStatus::Applied &&
                source_store->CommitTransaction() == apfsaccess::rw::MetadataStore::CommitStatus::Committed,
            "Accepted batch delete-hides-write source should persist its initial file"))
    {
        return false;
    }

    apfsaccess::rw::MetadataStore::PayloadIdentity write_identity{};
    apfsaccess::rw::MetadataStore::PayloadIdentity delete_identity{};
    std::vector<std::byte> payload(128, static_cast<std::byte>(0xA5));
    {
        apfsaccess::rw::MetadataStore::MutationRequest write{};
        write.operation = apfsaccess::rw::MetadataStore::MutationOperation::Write;
        write.path = create.path;
        write.offset = 0;
        write.length = payload.size();
        apfsaccess::rw::MetadataStore::MutationRequest remove{};
        remove.operation = apfsaccess::rw::MetadataStore::MutationOperation::Delete;
        remove.path = create.path;
        if (!Require(
                source_store->StageMutation(write, &write_identity) ==
                        apfsaccess::rw::MetadataStore::MutationStatus::Applied &&
                    source_store->StageMutation(remove, &delete_identity) ==
                        apfsaccess::rw::MetadataStore::MutationStatus::Applied &&
                    write_identity.object_id != 0 &&
                    write_identity.object_id == delete_identity.object_id,
                "Accepted batch delete-hides-write source should stage matching write and delete identities"))
        {
            return false;
        }
    }

    constexpr auto volume_identity = "accepted-batch-delete-hides-volume";
    const auto spool_root = run_root / "spool";
    const auto wal_path = spool_root / "write-ahead.wal";
    {
        apfsaccess::rw::PayloadSpool spool({spool_root, volume_identity, 1024 * 1024});
        apfsaccess::rw::TransactionManager tx(L"DeferredContent");
        tx.SetVolumeIdentity(L"accepted-batch-delete-hides-volume");
        tx.SetJournalPath(wal_path.wstring());
        apfsaccess::rw::PayloadSpool::AppendResult appended{};
        const auto write_sequence = tx.NextMutationSequence();
        if (!Require(
                spool.Append({
                    volume_identity,
                    write_identity.object_id,
                    write_identity.generation,
                    0,
                    write_sequence,
                    std::span<const std::byte>(payload.data(), payload.size()),
                }, &appended),
                "Accepted batch delete-hides-write source should stage the write payload"))
        {
            return false;
        }
        apfsaccess::rw::TransactionManager::MutationIntent wal_write{};
        wal_write.kind = apfsaccess::rw::TransactionManager::MutationKind::Write;
        wal_write.path = create.path;
        wal_write.length = appended.payload_length;
        wal_write.wal_sequence = write_sequence;
        wal_write.object_id = appended.object_id;
        wal_write.generation = appended.generation;
        wal_write.payload_spool_offset = appended.spool_offset;
        wal_write.payload_length = appended.payload_length;
        wal_write.payload_checksum = appended.payload_sha256;
        if (!Require(
                tx.Begin() && tx.RecordMutation(wal_write) && tx.Accept(),
                "Accepted batch delete-hides-write source should publish its write transaction"))
        {
            return false;
        }
        apfsaccess::rw::TransactionManager::MutationIntent wal_delete{};
        wal_delete.kind = apfsaccess::rw::TransactionManager::MutationKind::Delete;
        wal_delete.path = create.path;
        wal_delete.object_id = delete_identity.object_id;
        wal_delete.generation = delete_identity.generation;
        if (!Require(
                tx.Begin() && tx.RecordMutation(wal_delete) && tx.Accept(),
                "Accepted batch delete-hides-write source should publish its terminal delete transaction"))
        {
            return false;
        }
    }

    const auto checkpoint_before_replay = source_store->CheckpointXid();
    if (!Require(
            source_store->CommitTransaction() == apfsaccess::rw::MetadataStore::CommitStatus::Committed &&
                source_store->CheckpointXid() != checkpoint_before_replay,
            "Accepted batch delete-hides-write source should apply the whole accepted prefix in one checkpoint"))
    {
        return false;
    }
    const auto batch_checkpoint_xid = source_store->CheckpointXid();
    source_store.reset();

    const auto crash_spool_root = run_root / "crash-window-spool";
    std::error_code spool_copy_ec{};
    std::filesystem::copy(
        spool_root,
        crash_spool_root,
        std::filesystem::copy_options::recursive |
            std::filesystem::copy_options::overwrite_existing,
        spool_copy_ec);
    if (!Require(
            !spool_copy_ec,
            "Accepted batch delete-hides-write test should snapshot the spool for the crash window"))
    {
        return false;
    }

    const auto prepare_mount = [&](MountContext& context, const std::filesystem::path& journal, const std::filesystem::path& journal_spool_root)
    {
        context.args.device = image_path.wstring();
        context.args.volume = L"Main";
        context.args.readwrite = true;
        context.args.write_backend = L"Native";
        context.args.write_require_canonical_commit = false;
        context.args.write_disallow_scaffold_commit_on_non_fixture = false;
        context.args.write_reject_scaffold_replay_blob_on_non_fixture = false;
        context.args.write_require_canonical_replay_candidate_on_non_fixture = false;
        context.native_write_enabled = true;
        context.payload_spool_volume_identity = volume_identity;
        context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
            apfsaccess::rw::PayloadSpool::Options{journal_spool_root, volume_identity, 1024 * 1024});
        context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"DeferredContent");
        context.tx_manager->SetVolumeIdentity(L"accepted-batch-delete-hides-volume");
        context.tx_manager->SetJournalPath(journal.wstring());
        context.metadata_store = make_store();
        return context.metadata_store != nullptr;
    };

    MountContext context{};
    if (!Require(
            prepare_mount(context, wal_path, spool_root),
            "Accepted batch delete-hides-write replay should prepare metadata"))
    {
        return false;
    }
    const auto committed_inode =
        context.metadata_store->LookupCommittedInodeByObjectId(write_identity.object_id);
    if (!Require(
            !committed_inode.has_value(),
            "Accepted batch delete-hides-write replay should start from the terminal delete state"))
    {
        return false;
    }
    context.runtime_last_commit_xid = batch_checkpoint_xid;
    context.recovery_marker_file = run_root / "recovery.marker";
    if (!Require(
            UpdateRecoveryMarkerBestEffort(&context, false),
            "Accepted batch delete-hides-write replay should begin with a clean recovery marker"))
    {
        return false;
    }
    if (!Require(
            ArmRecoveryMarkerForPendingWriteAheadLog(context, true) &&
                context.pending_native_writes,
            "Accepted batch delete-hides-write replay should arm the recovery marker for the pending batch"))
    {
        return false;
    }

    const auto accepted_sequence = context.tx_manager->Watermarks().accepted_sequence;
    if (!Require(
            accepted_sequence != 0 && ReplayAcceptedWriteAheadLogAfterMetadataBootstrap(context),
            "Accepted batch delete-hides-write replay should converge from the batch"))
    {
        return false;
    }
    const auto watermarks = context.tx_manager->Watermarks();
    const auto checkpoint_after_replay = context.metadata_store->CheckpointXid();
    std::ifstream clean_marker_input(context.recovery_marker_file, std::ios::binary);
    const std::string clean_marker_text{
        std::istreambuf_iterator<char>(clean_marker_input),
        std::istreambuf_iterator<char>()};
    std::vector<std::byte> resurrected_payload;
    if (!Require(
            checkpoint_after_replay == batch_checkpoint_xid,
            "Batch replay should not create a duplicate checkpoint over the accepted prefix") ||
        !Require(
            watermarks.apfs_durable_sequence == accepted_sequence &&
                watermarks.cleanup_sequence == accepted_sequence,
            "Batch replay should converge durability and cleanup watermarks") ||
        !Require(
            !context.metadata_store->LookupCommittedInodeByObjectId(write_identity.object_id).has_value() &&
                !context.metadata_store->ReadCommittedFileRange(
                    L"\\batch-hide.bin",
                    0,
                    128,
                    resurrected_payload),
            "Batch replay must not resurrect a write hidden by a terminal delete in the same batch") ||
        !Require(
            !context.pending_native_writes && clean_marker_text.find("dirty=0") != std::string::npos,
            "Batch replay should clear the marker only after watermark convergence"))
    {
        return false;
    }
    context.tx_manager.reset();

    MountContext crash_context{};
    if (!Require(
            prepare_mount(crash_context, crash_spool_root / "write-ahead.wal", crash_spool_root),
            "Crash-window mount should prepare metadata"))
    {
        return false;
    }
    crash_context.runtime_last_commit_xid = batch_checkpoint_xid;
    crash_context.recovery_marker_file = run_root / "recovery-crash.marker";
    if (!Require(
            UpdateRecoveryMarkerBestEffort(&crash_context, false),
            "Crash-window mount should begin with a clean recovery marker"))
    {
        return false;
    }
    if (!Require(
            ArmRecoveryMarkerForPendingWriteAheadLog(crash_context, true),
            "Crash-window mount should arm the recovery marker for the replay checkpoint"))
    {
        return false;
    }
    const auto crash_accepted = crash_context.tx_manager->Watermarks().accepted_sequence;
    const auto replay_succeeded =
        ReplayAcceptedWriteAheadLogAfterMetadataBootstrap(crash_context);
    if (!Require(
            crash_accepted == accepted_sequence && replay_succeeded,
            "Crash-window replay should recognize the whole batch as already applied"))
    {
        return false;
    }
    const auto crash_watermarks = crash_context.tx_manager->Watermarks();
    const auto crash_checkpoint = crash_context.metadata_store->CheckpointXid();
    std::ifstream crash_marker_input(crash_context.recovery_marker_file, std::ios::binary);
    const std::string crash_marker_text{
        std::istreambuf_iterator<char>(crash_marker_input),
        std::istreambuf_iterator<char>()};
    return Require(
               crash_checkpoint == checkpoint_after_replay,
               "Crash-window replay should not create a duplicate APFS checkpoint") &&
           Require(
               crash_watermarks.apfs_durable_sequence == crash_accepted &&
                   crash_watermarks.cleanup_sequence == crash_accepted,
               "Crash-window replay should converge the previously pending watermarks") &&
           Require(
               !crash_context.metadata_store->LookupCommittedInodeByObjectId(write_identity.object_id).has_value(),
               "Crash-window replay should keep the deleted object absent") &&
           Require(
               !crash_context.pending_native_writes && crash_marker_text.find("dirty=0") != std::string::npos,
               "Crash-window replay should clear the marker only after watermark convergence");
#else
    return true;
#endif
}

bool TestAcceptedReplayRejectsMissingIdentity()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccessAcceptedNamespaceIdentity" /
        std::to_string(GetTickCount64());
    if (ec)
    {
        return Require(false, "Accepted namespace identity test should resolve temp directory");
    }
    std::filesystem::create_directories(run_root, ec);
    if (ec)
    {
        return Require(false, "Accepted namespace identity test should create temp directory");
    }
    ScopeExit cleanup{[&]() { std::filesystem::remove_all(run_root, ec); }};

    const auto image_path = run_root / "namespace-identity.apfs.img";
    if (!Require(
            CreateSyntheticApfsContainerForTest(image_path),
            "Accepted namespace identity test should create synthetic APFS image"))
    {
        return false;
    }

    const auto make_store = [&]()
    {
        apfsaccess::rw::MetadataStore::VolumeContext rw_context{
            image_path.wstring(),
            L"Main",
        };
        rw_context.allow_legacy_scaffold_for_fixtures = true;
        rw_context.disallow_scaffold_commit_on_non_fixture = false;
        rw_context.reject_scaffold_replay_blob_on_non_fixture = false;
        rw_context.require_canonical_replay_candidate_on_non_fixture = false;
        auto store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));
        if (!store->LoadContainerSuperblocks() ||
            !store->LoadObjectMap() ||
            !store->LoadSpacemanState() ||
            !store->PrepareNativeWritePath())
        {
            return std::unique_ptr<apfsaccess::rw::MetadataStore>{};
        }
        return store;
    };

    const auto replay_identity_less = [&](
        apfsaccess::rw::TransactionManager::MutationKind kind,
        const std::filesystem::path& case_root) -> bool
    {
        std::filesystem::create_directories(case_root, ec);
        if (ec)
        {
            return false;
        }
        const auto wal_path = case_root / "write-ahead.wal";
        std::uint64_t accepted_sequence = 0;
        {
            apfsaccess::rw::TransactionManager tx(L"NamespaceIdentity");
            tx.SetVolumeIdentity(L"accepted-namespace-identity");
            tx.SetJournalPath(wal_path.wstring());
            apfsaccess::rw::TransactionManager::MutationIntent mutation{};
            mutation.kind = kind;
            mutation.path = L"\\source.txt";
            if (kind == apfsaccess::rw::TransactionManager::MutationKind::Rename)
            {
                mutation.secondary_path = L"\\renamed.txt";
            }
            if (kind == apfsaccess::rw::TransactionManager::MutationKind::Write ||
                kind == apfsaccess::rw::TransactionManager::MutationKind::SetFileSize)
            {
                mutation.length = 4;
            }
            if (kind == apfsaccess::rw::TransactionManager::MutationKind::SetBasicInfo)
            {
                mutation.timestamp_utc = 0x01DABEEF;
            }
            if (!tx.Begin() || !tx.RecordMutation(mutation) || !tx.Accept())
            {
                return false;
            }
            accepted_sequence = tx.Watermarks().accepted_sequence;
        }

        MountContext context{};
        context.metadata_store = make_store();
        context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"NamespaceIdentity");
        context.tx_manager->SetVolumeIdentity(L"accepted-namespace-identity");
        context.tx_manager->SetJournalPath(wal_path.wstring());
        if (!context.metadata_store || accepted_sequence == 0)
        {
            return false;
        }

        const auto checkpoint_before = context.metadata_store->CheckpointXid();
        context.runtime_last_commit_xid = checkpoint_before;
        context.recovery_marker_file = case_root / "recovery.marker";
        if (!UpdateRecoveryMarkerBestEffort(&context, false) ||
            !ArmRecoveryMarkerForPendingWriteAheadLog(context, true))
        {
            return false;
        }
        const auto replayed = ReplayAcceptedWriteAheadLogAfterMetadataBootstrap(context);
        const auto checkpoint_after = context.metadata_store->CheckpointXid();
        std::ifstream marker_input(context.recovery_marker_file, std::ios::binary);
        const std::string marker_text{
            std::istreambuf_iterator<char>(marker_input),
            std::istreambuf_iterator<char>()};
        const auto namespace_mutation =
            kind == apfsaccess::rw::TransactionManager::MutationKind::Rename ||
            kind == apfsaccess::rw::TransactionManager::MutationKind::Delete;
        const auto expected_reason = namespace_mutation
            ? L"AcceptedNamespaceReplayIdentityMissing"
            : L"AcceptedReplayIdentityMissing";
        return !replayed &&
               context.runtime_recovery_reason == expected_reason &&
               context.tx_manager->Watermarks().apfs_durable_sequence < accepted_sequence &&
               context.pending_native_writes &&
               marker_text.find("dirty=1") != std::string::npos &&
               checkpoint_before == checkpoint_after;
    };

    return Require(
               replay_identity_less(
                   apfsaccess::rw::TransactionManager::MutationKind::CreateFile,
                   run_root / "create-file"),
               "Accepted identity-less file create replay should fail closed before metadata staging") &&
           Require(
               replay_identity_less(
                   apfsaccess::rw::TransactionManager::MutationKind::CreateDirectory,
                   run_root / "create-directory"),
               "Accepted identity-less directory create replay should fail closed before metadata staging") &&
           Require(
               replay_identity_less(
                   apfsaccess::rw::TransactionManager::MutationKind::Write,
                   run_root / "write"),
               "Accepted identity-less write replay should fail closed before metadata staging") &&
           Require(
               replay_identity_less(
                   apfsaccess::rw::TransactionManager::MutationKind::SetFileSize,
                   run_root / "set-file-size"),
               "Accepted identity-less file-size replay should fail closed before metadata staging") &&
           Require(
               replay_identity_less(
                   apfsaccess::rw::TransactionManager::MutationKind::SetBasicInfo,
                   run_root / "set-basic-info"),
               "Accepted identity-less basic-info replay should fail closed before metadata staging") &&
           Require(
               replay_identity_less(
                   apfsaccess::rw::TransactionManager::MutationKind::Rename,
                   run_root / "rename"),
               "Accepted identity-less rename replay should fail closed before metadata staging") &&
           Require(
               replay_identity_less(
                   apfsaccess::rw::TransactionManager::MutationKind::Delete,
                   run_root / "delete"),
               "Accepted identity-less delete replay should fail closed before metadata staging");
#else
    return true;
#endif
}

bool TestNativeJournalRejectsIdentityLessMutation()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    context.native_write_enabled = true;
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"NativeIdentity");

    const std::array<apfsaccess::rw::TransactionManager::MutationKind, 7> kinds{
        apfsaccess::rw::TransactionManager::MutationKind::CreateFile,
        apfsaccess::rw::TransactionManager::MutationKind::CreateDirectory,
        apfsaccess::rw::TransactionManager::MutationKind::Write,
        apfsaccess::rw::TransactionManager::MutationKind::SetFileSize,
        apfsaccess::rw::TransactionManager::MutationKind::SetBasicInfo,
        apfsaccess::rw::TransactionManager::MutationKind::Rename,
        apfsaccess::rw::TransactionManager::MutationKind::Delete,
    };
    for (const auto kind : kinds)
    {
        const auto next_sequence_before = context.tx_manager->NextMutationSequence();
        const auto length =
            kind == apfsaccess::rw::TransactionManager::MutationKind::Write ||
            kind == apfsaccess::rw::TransactionManager::MutationKind::SetFileSize
                ? 4ull
                : 0ull;
        const auto timestamp =
            kind == apfsaccess::rw::TransactionManager::MutationKind::SetBasicInfo
                ? 0x01DABEEF
                : 0ull;
        const auto secondary_path =
            kind == apfsaccess::rw::TransactionManager::MutationKind::Rename
                ? L"\\renamed.txt"
                : L"";
        if (!Require(
                !RecordMutationBestEffort(
                    &context,
                    kind,
                    L"\\identity-less.bin",
                    secondary_path,
                    0,
                    length,
                    false,
                    0,
                    timestamp),
                "Native journal should reject identity-less replayable mutation") ||
            !Require(
                context.tx_manager->NextMutationSequence() == next_sequence_before,
                "Rejected identity-less mutation should not consume a WAL sequence") ||
            !Require(
                context.tx_manager->CurrentState() == apfsaccess::rw::TransactionManager::State::Idle,
                "Rejected identity-less mutation should leave the transaction idle"))
        {
            return false;
        }
    }

    const apfsaccess::rw::MetadataStore::PayloadIdentity identity{ 77, 9 };
    return Require(
               RecordMutationBestEffort(
                   &context,
                   apfsaccess::rw::TransactionManager::MutationKind::CreateFile,
                   L"\\identity-bound.bin",
                   L"",
                   0,
                   0,
                   false,
                   0,
                   0,
                   &identity),
               "Native journal should accept an identity-bound mutation") &&
           Require(
               context.tx_manager->PendingMutationCount() == 1,
               "Identity-bound mutation should be recorded in the active transaction");
#else
    return true;
#endif
}

bool TestCloseCommitsPendingNativeMetadataAfterDirectoryCreate()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_recovery_policy = L"FailClosed";
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    context.test_force_native_mutation_staging_success = true;
    context.test_forced_native_commit_status = apfsaccess::rw::MetadataStore::CommitStatus::Committed;
    std::error_code ec;
    const auto marker_root = std::filesystem::temp_directory_path(ec) / "ApfsAccess" / "fs-host-semantics";
    if (ec)
    {
        return Require(false, "Close-commit regression should resolve temp directory");
    }
    std::filesystem::create_directories(marker_root, ec);
    if (ec)
    {
        return Require(false, "Close-commit regression should create marker directory");
    }
    context.recovery_marker_file = marker_root / (L"close-commit-" + std::to_wstring(GetTickCount64()) + L".state");
    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);

    auto fs = BuildFileSystem(&context);
    PVOID out_ctx = nullptr;
    FSP_FSCTL_FILE_INFO info{};
    const auto create_status = CB_Create(
        &fs,
        const_cast<PWSTR>(L"\\close-commit-dir"),
        FILE_DIRECTORY_FILE,
        FILE_WRITE_ATTRIBUTES,
        0,
        nullptr,
        0,
        &out_ctx,
        &info);
    if (!Require(create_status == STATUS_SUCCESS, "Directory create should succeed for close-commit regression"))
    {
        std::filesystem::remove(context.recovery_marker_file, ec);
        return false;
    }
    if (!Require(out_ctx != nullptr, "Directory create should return an open context for close-commit regression"))
    {
        std::filesystem::remove(context.recovery_marker_file, ec);
        return false;
    }
    if (!Require(context.pending_native_writes, "Directory create should mark native writes pending before close"))
    {
        CB_Close(&fs, out_ctx);
        std::filesystem::remove(context.recovery_marker_file, ec);
        return false;
    }

    CB_Close(&fs, out_ctx);

    const auto ok = Require(
        !context.pending_native_writes &&
        !context.recovery_active &&
        MutationAdmissionCount(context.mutation_admission_state.load(std::memory_order_acquire)) == 0,
        "Close should commit pending native metadata-only creates and publish a clean state");
    std::filesystem::remove(context.recovery_marker_file, ec);
    return ok;
#else
    return true;
#endif
}

bool TestCloseSkipsNativeCommitWhenMetadataIsClean()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_recovery_policy = L"FailClosed";
    context.native_write_enabled = true;
    context.overlay_write_enabled = true;
    context.pending_native_writes = true;
    context.test_forced_native_commit_status = apfsaccess::rw::MetadataStore::CommitStatus::PersistFailed;
    context.test_forced_native_commit_recovery_reason = L"UnexpectedCleanCloseCommit";
    context.test_forced_native_commit_recovery_required = true;
    std::error_code ec;
    const auto marker_root = std::filesystem::temp_directory_path(ec) / "ApfsAccess" / "fs-host-semantics";
    if (ec)
    {
        return Require(false, "Clean close commit-skip test should resolve temp directory");
    }
    std::filesystem::create_directories(marker_root, ec);
    if (ec)
    {
        return Require(false, "Clean close commit-skip test should create marker directory");
    }
    context.recovery_marker_file = marker_root / (L"clean-close-" + std::to_wstring(GetTickCount64()) + L".state");
    SeedRoot(context);

    auto file = MakeNode(L"\\clean.txt", false);
    context.nodes.emplace(Key(file->path), file);
    auto root = context.nodes[Key(L"\\")];
    root->children.push_back(L"clean.txt");

    auto* open_context = new OpenContext();
    open_context->node = file;
    open_context->write_open = true;
    file->open_handle_count = 1;
    file->write_handle_count = 1;

    auto fs = BuildFileSystem(&context);
    CB_Close(&fs, open_context);

    const auto ok = Require(
        context.test_native_commit_attempt_count == 0 &&
            !context.pending_native_writes &&
            !context.recovery_active &&
            context.native_write_enabled,
        "Close should clear a stale native dirty marker without attempting a commit when metadata is clean");
    std::filesystem::remove(context.recovery_marker_file, ec);
    return ok;
#else
    return true;
#endif
}

bool TestSetBasicInfoSkipsNativeMutationWhenTimestampUnchanged()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.native_write_enabled = true;
    context.overlay_write_enabled = true;
    context.test_force_native_mutation_staging_success = true;
    SeedRoot(context);

    auto file = MakeNode(L"\\same-time.txt", false);
    file->timestamp.dwLowDateTime = 0x12345678u;
    file->timestamp.dwHighDateTime = 0x01DABEEFu;
    context.nodes.emplace(Key(file->path), file);
    auto root = context.nodes[Key(L"\\")];
    root->children.push_back(L"same-time.txt");

    OpenContext open_context{};
    open_context.node = file;
    open_context.allow_set_basic_info = true;

    ULARGE_INTEGER timestamp{};
    timestamp.LowPart = file->timestamp.dwLowDateTime;
    timestamp.HighPart = file->timestamp.dwHighDateTime;

    auto fs = BuildFileSystem(&context);
    FSP_FSCTL_FILE_INFO info{};
    constexpr std::uint64_t foreground_tick_before = 12345;
    context.last_foreground_mutation_tick_ms.store(foreground_tick_before, std::memory_order_release);
    const auto no_timestamp_status = CB_SetBasicInfo(
        &fs,
        &open_context,
        FILE_ATTRIBUTE_NORMAL,
        0,
        0,
        0,
        0,
        &info);
    if (!Require(no_timestamp_status == STATUS_SUCCESS, "SetBasicInfo with no timestamp changes should succeed") ||
        !Require(context.test_forced_native_mutation_count == 0, "SetBasicInfo with zero timestamps should not stage a native mutation") ||
        !Require(!context.pending_native_writes, "SetBasicInfo with zero timestamps should not mark native writes pending") ||
        !Require(
            context.last_foreground_mutation_tick_ms.load(std::memory_order_acquire) == foreground_tick_before,
            "SetBasicInfo with zero timestamps should not enter foreground mutation tracking") ||
        !Require(
            MutationAdmissionCount(context.mutation_admission_state.load(std::memory_order_acquire)) == 0 &&
                context.active_foreground_mutation_callbacks.load(std::memory_order_acquire) == 0,
            "SetBasicInfo with zero timestamps should not enter mutation callback scopes") ||
        !Require(info.LastWriteTime == timestamp.QuadPart, "SetBasicInfo with zero timestamps should preserve the existing timestamp"))
    {
        return false;
    }

    const auto status = CB_SetBasicInfo(
        &fs,
        &open_context,
        0,
        0,
        0,
        timestamp.QuadPart,
        0,
        &info);

    return Require(status == STATUS_SUCCESS, "Unchanged SetBasicInfo should succeed") &&
        Require(context.test_forced_native_mutation_count == 0, "Unchanged SetBasicInfo should not stage a native mutation") &&
        Require(!context.pending_native_writes, "Unchanged SetBasicInfo should not mark native writes pending") &&
        Require(info.LastWriteTime == timestamp.QuadPart, "Unchanged SetBasicInfo should return the existing timestamp");
#else
    return true;
#endif
}

bool TestStatusFileIncludesCommitOriginPerformanceCounters()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_PERF_COUNTERS", L"1");
    ScopeExit clear_perf_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_PERF_COUNTERS", nullptr);
    }};

    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_recovery_policy = L"FailClosed";
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    context.pending_native_writes = true;
    context.test_force_native_mutation_staging_success = true;
    context.test_forced_native_commit_status = apfsaccess::rw::MetadataStore::CommitStatus::Committed;

    std::error_code ec;
    const auto status_root = std::filesystem::temp_directory_path(ec) / "ApfsAccess" / "fs-host-semantics";
    if (ec)
    {
        return Require(false, "Commit-origin status test should resolve temp directory");
    }
    std::filesystem::create_directories(status_root, ec);
    if (ec)
    {
        return Require(false, "Commit-origin status test should create status directory");
    }
    context.args.status_file = (status_root / (L"commit-origin-" + std::to_wstring(GetTickCount64()) + L".json")).wstring();
    context.recovery_marker_file = status_root / (L"commit-origin-" + std::to_wstring(GetTickCount64()) + L".state");

    const auto status = CommitNativeMutationsBestEffort(&context, L"Flush");
    if (!Require(status == STATUS_SUCCESS, "Forced commit-origin test commit should succeed"))
    {
        std::filesystem::remove(context.args.status_file, ec);
        std::filesystem::remove(context.recovery_marker_file, ec);
        return false;
    }

    std::ifstream in(context.args.status_file, std::ios::binary);
    const auto status_json = std::string{
        std::istreambuf_iterator<char>(in),
        std::istreambuf_iterator<char>()};
    const auto ok =
        Require(status_json.find("\"performance\":") != std::string::npos, "Status file should include performance payload when counters are enabled") &&
        Require(status_json.find("\"setVolumeLabel\":{\"count\":") != std::string::npos, "Status file should include SetVolumeLabel callback latency telemetry") &&
        Require(status_json.find("\"open\":{\"count\":") != std::string::npos, "Status file should include Open callback latency telemetry") &&
        Require(status_json.find("\"overwrite\":{\"count\":") != std::string::npos, "Status file should include Overwrite callback latency telemetry") &&
        Require(status_json.find("\"canDelete\":{\"count\":") != std::string::npos, "Status file should include CanDelete callback latency telemetry") &&
        Require(status_json.find("\"setSecurity\":{\"count\":") != std::string::npos, "Status file should include SetSecurity callback latency telemetry") &&
        Require(status_json.find("\"commitOrigins\":") != std::string::npos, "Status file should include commit-origin counters") &&
        Require(status_json.find("\"Flush\"") != std::string::npos, "Commit-origin counters should include Flush origin") &&
        Require(status_json.find("\"attempts\":1") != std::string::npos, "Flush commit-origin counter should record one attempt") &&
        Require(status_json.find("\"committed\":1") != std::string::npos, "Flush commit-origin counter should record one committed result") &&
        Require(status_json.find("\"recoveryMarker\":{\"count\":") != std::string::npos, "Status file should include recovery-marker latency telemetry") &&
        Require(status_json.find("\"closeCommitDeferred\":false") != std::string::npos, "Status file should include deferred close state");

    std::filesystem::remove(context.args.status_file, ec);
    std::filesystem::remove(context.recovery_marker_file, ec);
    return ok;
#else
    return true;
#endif
}

bool TestNativeCommitPolicyClassifiesSafetyBoundaries()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_recovery_policy = L"FailClosed";
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    context.pending_native_writes = true;
    context.test_force_native_mutation_staging_success = true;
    context.test_forced_native_commit_status = apfsaccess::rw::MetadataStore::CommitStatus::Committed;

    return
        Require(
            ClassifyNativeCommitRequest(&context, L"Flush", false, false) == NativeCommitUrgency::UserFlushMustCommit,
            "Flush should classify as a user durability boundary") &&
        Require(
            ClassifyNativeCommitRequest(&context, L"Rename", false, true) == NativeCommitUrgency::NamespaceBoundaryMustCommit,
            "Rename should classify as a namespace durability boundary") &&
        Require(
            ClassifyNativeCommitRequest(&context, L"Close", true, false) == NativeCommitUrgency::FileContentCloseCanDelay,
            "Delete-on-close should classify as a delayable close boundary") &&
        Require(
            ClassifyNativeCommitRequest(&context, L"DirtyLimit", false, false) == NativeCommitUrgency::DirtyLimitMustCommit,
            "Dirty-limit drains should classify as a forced safety boundary") &&
        Require(
            ClassifyNativeCommitRequest(&context, L"Close", false, false) == NativeCommitUrgency::FileContentCloseCanDelay,
            "Plain close should be identified as the future coalescing candidate");
#else
    return true;
#endif
}

bool TestCloseStagesNativeSubtreeDeleteBottomUp()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_recovery_policy = L"FailClosed";
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    context.args.allow_legacy_scaffold_for_fixtures = true;
    context.args.write_require_canonical_commit = false;
    context.args.write_disallow_scaffold_commit_on_non_fixture = false;
    context.args.write_reject_scaffold_replay_blob_on_non_fixture = false;
    context.args.write_require_canonical_replay_candidate_on_non_fixture = false;
    context.args.volume = L"SubtreeDelete";
    if (!Require(PrepareUnitHydrationRoot(context, L"native-subtree-delete"), "Native subtree delete test should prepare cache root"))
    {
        return false;
    }
    ScopeExit cleanup{[&]()
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
    }};

    const auto image_path = context.session_root / "subtree-delete.apfs.img";
    if (!Require(CreateSyntheticApfsContainerForTest(image_path), "Native subtree delete test should create synthetic APFS image"))
    {
        return false;
    }
    context.args.device = image_path.wstring();
    apfsaccess::rw::MetadataStore::VolumeContext rw_context{};
    rw_context.device_path = image_path.wstring();
    rw_context.volume_name = L"SubtreeDelete";
    rw_context.allow_legacy_scaffold_for_fixtures = true;
    rw_context.disallow_scaffold_commit_on_non_fixture = false;
    rw_context.reject_scaffold_replay_blob_on_non_fixture = false;
    rw_context.require_canonical_replay_candidate_on_non_fixture = false;
    context.metadata_store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));
    std::unordered_map<std::wstring, std::vector<std::byte>> staged_payloads;
    context.metadata_store->SetFilePayloadProvider(
        [&staged_payloads](const std::wstring& path, std::uint64_t logical_size) -> std::optional<std::vector<std::byte>>
        {
            auto it = staged_payloads.find(path);
            if (it == staged_payloads.end())
            {
                return std::nullopt;
            }
            auto payload = it->second;
            if (payload.size() < logical_size)
            {
                payload.resize(static_cast<std::size_t>(logical_size), std::byte{0});
            }
            else if (payload.size() > logical_size)
            {
                payload.resize(static_cast<std::size_t>(logical_size));
            }
            return payload;
        });
    if (!Require(context.metadata_store->LoadContainerSuperblocks(), "Native subtree delete test should load container superblocks") ||
        !Require(context.metadata_store->LoadObjectMap(), "Native subtree delete test should load object map") ||
        !Require(context.metadata_store->LoadSpacemanState(), "Native subtree delete test should load spaceman state") ||
        !Require(context.metadata_store->PrepareNativeWritePath(), "Native subtree delete test should prepare native write path"))
    {
        return false;
    }

    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);
    auto fs = BuildFileSystem(&context);

    auto create_directory = [&](PCWSTR path) -> bool
    {
        PVOID created_ctx = nullptr;
        FSP_FSCTL_FILE_INFO info{};
        const auto status = CB_Create(
            &fs,
            const_cast<PWSTR>(path),
            FILE_DIRECTORY_FILE,
            FILE_WRITE_ATTRIBUTES | DELETE,
            0,
            nullptr,
            0,
            &created_ctx,
            &info);
        if (!Require(status == STATUS_SUCCESS && created_ctx != nullptr, "Native subtree delete test should create directory"))
        {
            return false;
        }
        CB_Close(&fs, created_ctx);
        return true;
    };
    if (!create_directory(L"\\tree") || !create_directory(L"\\tree\\child"))
    {
        return false;
    }

    PVOID file_ctx = nullptr;
    FSP_FSCTL_FILE_INFO file_info{};
    const auto file_create = CB_Create(
        &fs,
        const_cast<PWSTR>(L"\\tree\\child\\payload.bin"),
        FILE_NON_DIRECTORY_FILE,
        FILE_WRITE_DATA | FILE_READ_DATA | DELETE,
        0,
        nullptr,
        0,
        &file_ctx,
        &file_info);
    if (!Require(file_create == STATUS_SUCCESS && file_ctx != nullptr, "Native subtree delete test should create payload file"))
    {
        return false;
    }
    const auto payload = BuildPatternPayloadForTest(1536, 0x42);
    ULONG written = 0;
    const auto write_status = CB_Write(
        &fs,
        file_ctx,
        const_cast<std::byte*>(payload.data()),
        0,
        static_cast<ULONG>(payload.size()),
        FALSE,
        FALSE,
        &written,
        &file_info);
    staged_payloads[L"\\tree\\child\\payload.bin"] = payload;
    CB_Close(&fs, file_ctx);
    if (!Require(write_status == STATUS_SUCCESS && written == payload.size(), "Native subtree delete test should write payload bytes"))
    {
        return false;
    }

    auto payload_node = FindNode(&context, L"\\tree\\child\\payload.bin");
    if (!Require(payload_node != nullptr, "Native subtree delete test should find payload before cleanup"))
    {
        return false;
    }
    auto* payload_delete = new OpenContext();
    payload_delete->node = payload_node;
    payload_delete->allow_delete = true;
    ++payload_node->open_handle_count;
    CB_Cleanup(&fs, payload_delete, const_cast<PWSTR>(L"\\tree\\child\\payload.bin"), FspCleanupDelete);
    CB_Close(&fs, payload_delete);
    staged_payloads.erase(L"\\tree\\child\\payload.bin");
    if (!Require(!context.recovery_active, "Native subtree delete should not degrade after payload delete"))
    {
        return false;
    }
    if (!Require(context.nodes.find(Key(L"\\tree\\child\\payload.bin")) == context.nodes.end(), "Native subtree delete should remove local payload"))
    {
        return false;
    }

    auto child = FindNode(&context, L"\\tree\\child");
    if (!Require(child != nullptr, "Native subtree delete test should find child directory after payload delete"))
    {
        return false;
    }
    auto* child_delete = new OpenContext();
    child_delete->node = child;
    child_delete->allow_delete = true;
    ++child->open_handle_count;
    CB_Cleanup(&fs, child_delete, const_cast<PWSTR>(L"\\tree\\child"), FspCleanupDelete);
    CB_Close(&fs, child_delete);
    if (!Require(!context.recovery_active, "Native subtree delete should not degrade after child directory delete"))
    {
        return false;
    }
    if (!Require(context.nodes.find(Key(L"\\tree\\child")) == context.nodes.end(), "Native subtree delete should remove local child directory"))
    {
        return false;
    }

    auto root = FindNode(&context, L"\\tree");
    if (!Require(root != nullptr, "Native subtree delete test should find root directory after child delete"))
    {
        return false;
    }
    auto* root_delete = new OpenContext();
    root_delete->node = root;
    root_delete->allow_delete = true;
    ++root->open_handle_count;
    CB_Cleanup(&fs, root_delete, const_cast<PWSTR>(L"\\tree"), FspCleanupDelete);
    CB_Close(&fs, root_delete);

    if (!Require(!context.recovery_active, "Native subtree delete should not degrade after root directory delete"))
    {
        return false;
    }
    if (!Require(context.nodes.find(Key(L"\\tree")) == context.nodes.end(), "Native subtree delete should remove local root"))
    {
        return false;
    }

    OpenContext flush_context{};
    flush_context.node = context.nodes.at(Key(L"\\"));
    FSP_FSCTL_FILE_INFO flush_info{};
    const auto flush_status = CB_Flush(&fs, &flush_context, &flush_info);
    if (!Require(flush_status == STATUS_SUCCESS, "Native subtree delete should drain deferred delete commits on flush"))
    {
        return false;
    }
    if (!Require(!context.metadata_store->LookupCommittedInodeByPath(L"\\tree").has_value(), "Native subtree delete should remove committed root"))
    {
        return false;
    }
    return Require(
        context.metadata_store->PendingMutationCount() == 0,
        "Native subtree delete should drain all bottom-up staged mutations on close");
#else
    return true;
#endif
}

bool TestStatusFileIncludesNativeMutationFailureDetail()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_recovery_policy = L"FailClosed";
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    context.args.allow_legacy_scaffold_for_fixtures = true;
    context.args.write_require_canonical_commit = false;
    context.args.write_disallow_scaffold_commit_on_non_fixture = false;
    context.args.write_reject_scaffold_replay_blob_on_non_fixture = false;
    context.args.write_require_canonical_replay_candidate_on_non_fixture = false;
    context.args.volume = L"FailureDetail";
    if (!Require(PrepareUnitHydrationRoot(context, L"native-mutation-failure-detail"), "Native mutation failure-detail test should prepare cache root"))
    {
        return false;
    }
    ScopeExit cleanup{[&]()
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
    }};

    const auto image_path = context.session_root / "failure-detail.apfs.img";
    if (!Require(CreateSyntheticApfsContainerForTest(image_path), "Native mutation failure-detail test should create synthetic APFS image"))
    {
        return false;
    }
    context.args.device = image_path.wstring();
    context.args.status_file = (context.session_root / "status.json").wstring();

    apfsaccess::rw::MetadataStore::VolumeContext rw_context{};
    rw_context.device_path = image_path.wstring();
    rw_context.volume_name = L"FailureDetail";
    rw_context.allow_legacy_scaffold_for_fixtures = true;
    rw_context.disallow_scaffold_commit_on_non_fixture = false;
    rw_context.reject_scaffold_replay_blob_on_non_fixture = false;
    rw_context.require_canonical_replay_candidate_on_non_fixture = false;
    context.metadata_store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));
    if (!Require(context.metadata_store->LoadContainerSuperblocks(), "Native mutation failure-detail test should load container superblocks") ||
        !Require(context.metadata_store->LoadObjectMap(), "Native mutation failure-detail test should load object map") ||
        !Require(context.metadata_store->LoadSpacemanState(), "Native mutation failure-detail test should load spaceman state") ||
        !Require(context.metadata_store->PrepareNativeWritePath(), "Native mutation failure-detail test should prepare native write path"))
    {
        return false;
    }

    const auto staged = RecordNativeMutationBestEffort(
        &context,
        apfsaccess::rw::MetadataStore::MutationOperation::SetBasicInfo,
        L"\\missing-after-delete.txt",
        L"",
        0,
        0,
        false,
        ToFileTimeValue(UtcNow()));
    if (!Require(!staged, "Native mutation failure-detail test should reject missing SetBasicInfo target"))
    {
        return false;
    }

    (void)BlockNativeMutationAfterStagingFailure(&context, L"SetBasicInfo");

    std::ifstream in(std::filesystem::path(context.args.status_file), std::ios::binary);
    if (!Require(in.good(), "Native mutation failure-detail test should open host status sidecar"))
    {
        return false;
    }
    std::stringstream buffer;
    buffer << in.rdbuf();
    const auto json = buffer.str();

    return Require(
            !context.unjournaled_native_mutation.load(std::memory_order_acquire),
            "A clean native metadata rejection must not latch unjournaled staged work") &&
        Require(json.find("\"lastNativeMutationFailure\":{") != std::string::npos, "Status sidecar should include native mutation failure detail object") &&
        Require(json.find("\"operation\":\"SetBasicInfo\"") != std::string::npos, "Status sidecar should report failed native mutation operation") &&
        Require(json.find("\"path\":\"\\\\missing-after-delete.txt\"") != std::string::npos, "Status sidecar should report failed native mutation path") &&
        Require(json.find("\"status\":\"invalid-request\"") != std::string::npos, "Status sidecar should report failed native mutation status") &&
        Require(json.find("\"reason\":\"SetBasicInfoTargetMissing\"") != std::string::npos, "Status sidecar should report failed native mutation reason");
#else
    return true;
#endif
}

