bool TestExternalMutationScopeTracksActiveCountAndDrainGate()
{
    MountContext context{};

    {
        ExternalMutationRequestScope first_scope(&context);
        if (!Require(first_scope.Acquired(), "First external mutation scope should acquire when drain is inactive"))
        {
            return false;
        }
        if (!Require(MutationAdmissionCount(context.mutation_admission_state.load(std::memory_order_acquire)) == 1, "Acquired external mutation scope should increment active counter"))
        {
            return false;
        }

        context.mutation_admission_state.fetch_or(kMutationAdmissionDrainFlag, std::memory_order_seq_cst);
        ExternalMutationRequestScope blocked_scope(&context);
        if (!Require(!blocked_scope.Acquired(), "External mutation scope should be rejected once shutdown drain is active"))
        {
            return false;
        }
        if (!Require(MutationAdmissionCount(context.mutation_admission_state.load(std::memory_order_acquire)) == 1, "Rejected external mutation scope must not increment active counter"))
        {
            return false;
        }
    }

    return Require(MutationAdmissionCount(context.mutation_admission_state.load(std::memory_order_acquire)) == 0, "Destroying acquired external mutation scope should decrement active counter");
}

bool TestBeginMutationShutdownDrainWaitsForInFlightMutation()
{
    MountContext context{};
    context.args.write_commit_timeout_seconds = 2;
    context.mutation_admission_state.store(0, std::memory_order_release);
    context.mutation_admission_state.store(0, std::memory_order_release);

    std::atomic<bool> worker_entered{false};
    std::thread worker([&]()
    {
        ExternalMutationRequestScope scope(&context);
        if (!scope.Acquired())
        {
            return;
        }
        worker_entered.store(true);
        std::this_thread::sleep_for(std::chrono::milliseconds(200));
    });

    const auto wait_started = std::chrono::steady_clock::now();
    while (!worker_entered.load())
    {
        if (std::chrono::steady_clock::now() - wait_started > std::chrono::seconds(1))
        {
            worker.join();
            return Require(false, "Worker failed to enter external mutation scope before drain wait test");
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }

    const auto drain_started = std::chrono::steady_clock::now();
    const auto drained = BeginMutationShutdownDrain(&context);
    const auto drain_elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::steady_clock::now() - drain_started);

    worker.join();

    if (!Require(MutationAdmissionIsDraining(context.mutation_admission_state.load(std::memory_order_acquire)), "BeginMutationShutdownDrain should latch shutdown drain active"))
    {
        return false;
    }
    if (!Require(drained, "Shutdown drain should report success when callbacks finish before the timeout"))
    {
        return false;
    }
    if (!Require(drain_elapsed.count() >= 120, "Drain should wait for in-flight mutation callbacks to complete"))
    {
        return false;
    }
    if (!Require(drain_elapsed.count() < 1500, "Drain should not exceed configured timeout when callback completes in time"))
    {
        return false;
    }

    return Require(MutationAdmissionCount(context.mutation_admission_state.load(std::memory_order_acquire)) == 0, "Drain wait completion should leave no active external mutation callbacks");
}

bool TestBeginMutationShutdownDrainTimesOutWithStuckMutation()
{
    MountContext context{};
    context.args.write_commit_timeout_seconds = 1;
    context.mutation_admission_state.store(0, std::memory_order_release);
    context.mutation_admission_state.store(0, std::memory_order_release);

    std::atomic<bool> worker_entered{false};
    std::thread worker([&]()
    {
        ExternalMutationRequestScope scope(&context);
        if (!scope.Acquired())
        {
            return;
        }
        worker_entered.store(true);
        std::this_thread::sleep_for(std::chrono::milliseconds(1800));
    });

    const auto wait_started = std::chrono::steady_clock::now();
    while (!worker_entered.load())
    {
        if (std::chrono::steady_clock::now() - wait_started > std::chrono::seconds(1))
        {
            worker.join();
            return Require(false, "Worker failed to enter external mutation scope before drain-timeout test");
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }

    const auto drain_started = std::chrono::steady_clock::now();
    const auto drained = BeginMutationShutdownDrain(&context);
    const auto drain_elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::steady_clock::now() - drain_started);

    if (!Require(MutationAdmissionIsDraining(context.mutation_admission_state.load(std::memory_order_acquire)), "Drain timeout path should still latch shutdown drain active"))
    {
        worker.join();
        return false;
    }
    if (!Require(!drained, "Shutdown drain should report failure when callbacks remain active at timeout"))
    {
        worker.join();
        return false;
    }
    if (!Require(drain_elapsed.count() >= 850, "Drain timeout should wait approximately the configured timeout window"))
    {
        worker.join();
        return false;
    }
    if (!Require(drain_elapsed.count() < 1700, "Drain timeout should return promptly after timeout window"))
    {
        worker.join();
        return false;
    }
    if (!Require(MutationAdmissionCount(context.mutation_admission_state.load(std::memory_order_acquire)) > 0, "Drain timeout should return while stuck mutation callback is still active"))
    {
        worker.join();
        return false;
    }

    worker.join();
    return Require(MutationAdmissionCount(context.mutation_admission_state.load(std::memory_order_acquire)) == 0, "Active mutation callback count should clear once stuck callback completes");
}

bool TestFsHostShutdownExitCodeRequiresEveryDrainStageToSucceed()
{
    return Require(
               ResolveFsHostShutdownExitCode(true, STATUS_SUCCESS, true) == 0,
               "Successful callback, APFS, and journal drains should produce a clean host exit") &&
           Require(
               ResolveFsHostShutdownExitCode(false, STATUS_SUCCESS, true) != 0,
               "Callback drain timeout should produce a failing host exit") &&
           Require(
               ResolveFsHostShutdownExitCode(true, STATUS_UNSUCCESSFUL, true) != 0,
               "APFS drain failure should produce a failing host exit") &&
           Require(
               ResolveFsHostShutdownExitCode(true, STATUS_SUCCESS, false) != 0,
               "Journal finalization failure should produce a failing host exit");
}

bool TestCommitTimeoutBudgetScalesWithPendingPayload()
{
    const auto empty_budget = ComputeWriteCommitTimeoutBudgetSeconds(15, 0);
    if (!Require(empty_budget == 15, "Commit timeout budget should preserve configured timeout for metadata-only commits"))
    {
        return false;
    }

    const auto large_budget = ComputeWriteCommitTimeoutBudgetSeconds(15, 1ull * 1024ull * 1024ull * 1024ull);
    if (!Require(large_budget > 15, "Commit timeout budget should grow for large pending payload commits"))
    {
        return false;
    }
    if (!Require(large_budget <= 180, "Commit timeout budget should remain capped for large pending payload commits"))
    {
        return false;
    }

    const auto measured_physical_budget = ComputeWriteCommitTimeoutBudgetSeconds(
        15,
        64ull * 1024ull * 1024ull);
    if (!Require(
            measured_physical_budget == 27,
            "Commit timeout budget should include bounded checkpoint headroom for the measured 64 MiB physical commit"))
    {
        return false;
    }

    const auto capped_budget = ComputeWriteCommitTimeoutBudgetSeconds(
        15,
        std::numeric_limits<std::uint64_t>::max());
    if (!Require(capped_budget == 180, "Commit timeout budget should cap extreme pending payload estimates"))
    {
        return false;
    }
    if (!Require(
            ComputeWriteCommitTimeoutBudgetSeconds(240, 1ull * 1024ull * 1024ull) == 240,
            "Commit timeout budget should preserve explicit configured timeouts above the payload extension cap"))
    {
        return false;
    }

    return Require(
        ComputeWriteCommitTimeoutBudgetSeconds(0, 0) == 1,
        "Commit timeout budget should clamp invalid configured timeouts to one second");
}

