bool TestEnsureDirectoryLoadedUsesCommittedChildIndexBeforeSnapshot()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    context.args.volume = L"Main";
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_require_canonical_commit = false;
    context.args.write_disallow_scaffold_commit_on_non_fixture = false;
    context.args.write_reject_scaffold_replay_blob_on_non_fixture = false;
    context.args.write_require_canonical_replay_candidate_on_non_fixture = false;
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);
    if (!Require(PrepareUnitHydrationRoot(context, L"ensure-directory-loaded-committed-child-index"), "Directory child-index load test should prepare cache root") ||
        !Require(ConfigureUnitRecoveryMarker(context, L"ensure-directory-loaded-committed-child-index"), "Directory child-index load test should configure recovery marker"))
    {
        return false;
    }

    std::error_code ec;
    ScopeExit cleanup{[&]()
    {
        std::filesystem::remove(context.recovery_marker_file, ec);
        std::filesystem::remove_all(context.session_root, ec);
    }};

    const auto image_path = context.session_root / "ensure-directory-loaded-committed-child-index.apfs.img";
    if (!Require(CreateSyntheticApfsContainerForTest(image_path), "Directory child-index load test should create synthetic APFS image"))
    {
        return false;
    }
    context.args.device = image_path.wstring();

    apfsaccess::rw::MetadataStore::VolumeContext rw_context
    {
        image_path.wstring(),
        L"Main",
    };
    context.metadata_store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));

    {
        std::lock_guard<std::mutex> metadata_lock(context.metadata_mutex);
        if (!Require(context.metadata_store->LoadContainerSuperblocks(), "Directory child-index load test should load container superblocks") ||
            !Require(context.metadata_store->LoadObjectMap(), "Directory child-index load test should load object map") ||
            !Require(context.metadata_store->LoadSpacemanState(), "Directory child-index load test should load spaceman state") ||
            !Require(context.metadata_store->PrepareNativeWritePath(), "Directory child-index load test should prepare native write path"))
        {
            return false;
        }

        apfsaccess::rw::MetadataStore::MutationRequest create_directory{};
        create_directory.operation = apfsaccess::rw::MetadataStore::MutationOperation::CreateDirectory;
        create_directory.path = L"\\bulk";
        if (!Require(
                context.metadata_store->ApplyMutation(create_directory) == apfsaccess::rw::MetadataStore::MutationStatus::Applied,
                "Directory child-index load test should create bulk directory"))
        {
            return false;
        }

        for (int i = 0; i < 64; ++i)
        {
            apfsaccess::rw::MetadataStore::MutationRequest create_child{};
            create_child.operation = apfsaccess::rw::MetadataStore::MutationOperation::CreateFile;
            create_child.path = L"\\bulk\\file-" + std::to_wstring(i) + L".txt";
            if (!Require(
                    context.metadata_store->ApplyMutation(create_child) == apfsaccess::rw::MetadataStore::MutationStatus::Applied,
                    "Directory child-index load test should create child file"))
            {
                return false;
            }
        }

        if (!Require(
                context.metadata_store->CommitPendingMutations() == apfsaccess::rw::MetadataStore::CommitStatus::Committed,
                "Directory child-index load test should commit children"))
        {
            return false;
        }
    }

    if (!Require(MergeCommittedInodeStateIntoNodeIndex(&context), "Directory child-index load test should seed host inode state"))
    {
        return false;
    }

    auto root = FindNode(&context, L"\\");
    auto bulk = FindNode(&context, L"\\bulk");
    if (!Require(root != nullptr && root->is_directory, "Full committed inode merge should find the root directory") ||
        !Require(bulk != nullptr && bulk->is_directory, "Full committed inode merge should find bulk directory") ||
        !Require(HasChildName(root->children, L"bulk"), "Full committed inode merge should link bulk into the root directory") ||
        !Require(HasChildName(bulk->children, L"file-0.txt"), "Full committed inode merge should link the first committed child") ||
        !Require(HasChildName(bulk->children, L"file-63.txt"), "Full committed inode merge should link the last committed child"))
    {
        return false;
    }

    auto fs = BuildFileSystem(&context);
    context.api.AddDir = [](FSP_FSCTL_DIR_INFO* entry, PVOID, ULONG, PULONG done) -> BOOLEAN
    {
        if (entry && done)
        {
            ++*done;
        }
        return TRUE;
    };
    std::array<std::byte, 4096> buffer{};
    OpenContext root_context{};
    root_context.node = root;
    root_context.allow_list_directory = true;
    ULONG root_entries = 0;
    if (!Require(
            CB_ReadDirectory(
                &fs,
                &root_context,
                nullptr,
                nullptr,
                buffer.data(),
                static_cast<ULONG>(buffer.size()),
                &root_entries) == STATUS_SUCCESS,
            "Full committed inode merge should enumerate the root directory") ||
        !Require(root_entries == 1, "Full committed inode merge should enumerate the committed root child"))
    {
        return false;
    }

    OpenContext bulk_context{};
    bulk_context.node = bulk;
    bulk_context.allow_list_directory = true;
    ULONG bulk_entries = 0;
    if (!Require(
            CB_ReadDirectory(
                &fs,
                &bulk_context,
                nullptr,
                nullptr,
                buffer.data(),
                static_cast<ULONG>(buffer.size()),
                &bulk_entries) == STATUS_SUCCESS,
            "Full committed inode merge should enumerate a committed subdirectory") ||
        !Require(bulk_entries == 64, "Full committed inode merge should enumerate every committed file"))
    {
        return false;
    }

    {
        std::lock_guard<std::mutex> lock(context.mutex);
        ClearChildNames(*bulk);
        bulk->loaded = false;
        for (int i = 0; i < 64; ++i)
        {
            const auto child_path = L"\\bulk\\file-" + std::to_wstring(i) + L".txt";
            if (auto child = TryGetNodeLockedNormalized(&context, child_path))
            {
                EraseIndexedNodeLocked(&context, child);
            }
        }
    }

    const auto before_json = context.metadata_store->PerformanceJson();
    const auto before_snapshot_count = ExtractPerfCounterCount(before_json, "snapshotCommittedInodes");
    if (!Require(before_snapshot_count.has_value(), "Directory child-index load test should read snapshot counter before load"))
    {
        return false;
    }

    if (!Require(EnsureDirectoryLoaded(&context, bulk), "Directory child-index load test should load bulk directory"))
    {
        return false;
    }

    const auto after_json = context.metadata_store->PerformanceJson();
    const auto after_snapshot_count = ExtractPerfCounterCount(after_json, "snapshotCommittedInodes");
    if (!Require(
            after_snapshot_count.has_value() && after_snapshot_count.value() == before_snapshot_count.value(),
            "Directory child-index load test should not fall back to a full committed inode snapshot"))
    {
        return false;
    }

    auto reloaded = FindNode(&context, L"\\bulk");
    return Require(reloaded != nullptr && reloaded->loaded, "Directory child-index load test should mark directory loaded") &&
           Require(HasChildName(reloaded->children, L"file-0.txt"), "Directory child-index load test should restore first child") &&
           Require(HasChildName(reloaded->children, L"file-63.txt"), "Directory child-index load test should restore last child");
#else
    return true;
#endif
}

