bool TestRecoveryIdentityBlockCannotBeClearedByMetadataReplay()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    context.args.volume = L"Main";
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.recovery_identity = kRecoveryIdentityA;
    context.recovery_identity_blocked = true;
    context.pending_native_writes = true;
    context.recovery_active = true;
    context.write_degraded = true;
    context.native_write_enabled = false;
    context.runtime_recovery_reason = L"LegacyRecoveryEvidenceAmbiguous";
    context.runtime_last_recovery_action = L"StartupBlockedByLegacyRecoveryEvidence";
    if (!Require(
            PrepareUnitHydrationRoot(context, L"recovery-identity-block-no-reenable"),
            "Identity-block test should prepare its D-drive temp root") ||
        !Require(
            ConfigureUnitRecoveryMarker(context, L"recovery-identity-block-no-reenable"),
            "Identity-block test should configure its recovery marker"))
    {
        return false;
    }

    std::error_code ec;
    const auto image_path = context.session_root / "recovery-identity-block.apfs.img";
    if (!Require(
            CreateSyntheticApfsContainerForTest(image_path),
            "Identity-block test should create a synthetic APFS image"))
    {
        std::filesystem::remove_all(context.session_root, ec);
        std::filesystem::remove(context.recovery_marker_file, ec);
        return false;
    }
    context.args.device = image_path.wstring();

    apfsaccess::rw::MetadataStore::VolumeContext rw_context
    {
        image_path.wstring(),
        L"Main",
    };
    context.metadata_store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));
    {
        std::lock_guard<std::mutex> metadata_lock(context.metadata_mutex);
        if (!Require(
                context.metadata_store->LoadContainerSuperblocks(),
                "Identity-block test should load container superblocks") ||
            !Require(
                context.metadata_store->LoadObjectMap(),
                "Identity-block test should load the object map") ||
            !Require(
                context.metadata_store->LoadSpacemanState(),
                "Identity-block test should load spaceman state") ||
            !Require(
                context.metadata_store->PrepareNativeWritePath(),
                "Identity-block test should prepare a clean metadata path"))
        {
            std::filesystem::remove_all(context.session_root, ec);
            std::filesystem::remove(context.recovery_marker_file, ec);
            return false;
        }
    }
    context.runtime_last_commit_xid = ResolveCleanRecoveryCheckpointXid(*context.metadata_store);
    if (!Require(
            context.runtime_last_commit_xid.has_value(),
            "Identity-block test should resolve a clean checkpoint xid"))
    {
        std::filesystem::remove_all(context.session_root, ec);
        std::filesystem::remove(context.recovery_marker_file, ec);
        return false;
    }

    ClearRecoveredMarkerIfClean(context, L"RecoveryMarkerClearedAfterReplay");
    std::filesystem::remove_all(context.session_root, ec);
    std::filesystem::remove(context.recovery_marker_file, ec);
    return Require(context.recovery_identity_blocked, "Metadata replay should not clear the immutable identity policy") &&
           Require(context.pending_native_writes, "Metadata replay should retain ambiguous recovery evidence") &&
           Require(context.recovery_active, "Metadata replay should preserve the identity recovery signal") &&
           Require(context.write_degraded, "Metadata replay should preserve degraded write state") &&
           Require(!context.native_write_enabled, "Metadata replay should not re-enable native writes") &&
           Require(
               context.runtime_recovery_reason == L"LegacyRecoveryEvidenceAmbiguous",
               "Metadata replay should preserve the identity policy status reason");
#else
    return true;
#endif
}

