bool TestLegacyMixedWalScansAllIdentitiesForMatchingEvidence()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        "legacy-mixed-wal-identities";
    if (!Require(!ec, "Mixed WAL test should resolve the D-drive temp root"))
    {
        return false;
    }
    std::filesystem::remove_all(run_root, ec);
    const auto spool_base = run_root / "spool";
    const auto legacy_root = spool_base / "mixed-identities";
    std::filesystem::create_directories(legacy_root, ec);
    if (!Require(!ec, "Mixed WAL test should create its spool root"))
    {
        return false;
    }

    Arguments current_legacy{};
    current_legacy.device = L"\\\\.\\PhysicalDrive2";
    current_legacy.device_offset_bytes = 1048576;
    current_legacy.volume = L"Main";
    current_legacy.write_backend = L"Native";

    Arguments unrelated_one = current_legacy;
    unrelated_one.volume = L"OtherOne";
    Arguments unrelated_two = current_legacy;
    unrelated_two.volume = L"OtherTwo";

    const auto make_record = [](std::uint64_t sequence, const std::wstring& identity)
    {
        apfsaccess::rw::WriteAheadLog::Record record{};
        record.volume_identity = WideToUtf8(identity);
        record.transaction_id = sequence;
        record.sequence = sequence;
        record.operation = apfsaccess::rw::WriteAheadLog::OperationKind::CreateFile;
        record.state = apfsaccess::rw::WriteAheadLog::RecordState::Prepared;
        record.object_id = 40 + sequence;
        record.path_utf8 = "\\\\legacy-" + std::to_string(sequence) + ".bin";
        return record;
    };

    {
        const std::vector<apfsaccess::rw::WriteAheadLog::Record> records
        {
            make_record(1, BuildLegacyWalVolumeIdentity(unrelated_one)),
            make_record(2, BuildLegacyWalVolumeIdentity(unrelated_two)),
            make_record(3, BuildLegacyWalVolumeIdentity(current_legacy)),
        };
        std::ofstream legacy_wal(legacy_root / "write-ahead.wal", std::ios::binary | std::ios::trunc);
        for (const auto& record : records)
        {
            const auto encoded = apfsaccess::rw::WriteAheadLog::EncodeForTest(record);
            legacy_wal.write(
                reinterpret_cast<const char*>(encoded.data()),
                static_cast<std::streamsize>(encoded.size()));
        }
        if (!Require(
                legacy_wal.good(),
                "Mixed WAL test should persist all legacy identity records"))
        {
            std::filesystem::remove_all(run_root, ec);
            return false;
        }
    }

    Arguments current = current_legacy;
    current.device = L"\\\\.\\PhysicalDrive9";
    current.recovery_identity = kRecoveryIdentityA;
    const auto ambiguous = FindAmbiguousLegacyRecoveryEvidence(
        current,
        spool_base,
        run_root / "recovery");
    std::filesystem::remove_all(run_root, ec);
    return Require(
        ambiguous.has_value() && ambiguous.value() == legacy_root,
        "Mixed legacy WAL should scan every identity and block when a later record matches this volume");
#else
    return true;
#endif
}

