bool TestFsHostPerformanceCounterReportsPercentile()
{
    PerfCounter zero_counter{};
    zero_counter.Observe(0);
    if (!Require(zero_counter.max_us.load(std::memory_order_relaxed) == 0,
            "FsHost zero-latency maximum should remain zero") ||
        !Require(zero_counter.ApproxP50Us() == 0,
            "FsHost zero-latency p50 should remain zero") ||
        !Require(zero_counter.ApproxP95Us() == 0,
            "FsHost zero-latency p95 should remain zero"))
    {
        return false;
    }

    PerfCounter counter{};
    counter.Observe(0);
    counter.Observe(1);
    counter.Observe(2);
    counter.Observe(4);
    if (!Require(counter.ApproxP50Us() == 1, "FsHost p50 should use the exact nearest-rank bucket") ||
        !Require(counter.ApproxP95Us() == 4, "FsHost p95 should use the exact nearest-rank bucket"))
    {
        return false;
    }

    PerfCounter p95_boundary{};
    p95_boundary.count.store(20, std::memory_order_relaxed);
    p95_boundary.max_us.store(2, std::memory_order_relaxed);
    p95_boundary.latency_buckets[0].store(19, std::memory_order_relaxed);
    p95_boundary.latency_buckets[1].store(1, std::memory_order_relaxed);
    if (!Require(p95_boundary.ApproxP95Us() == 1,
            "FsHost p95 rank should be ceil(19 * count / 20)"))
    {
        return false;
    }

    const auto max_u64 = (std::numeric_limits<std::uint64_t>::max)();
    PerfCounter rank_boundary{};
    rank_boundary.count.store(max_u64, std::memory_order_relaxed);
    rank_boundary.max_us.store(4, std::memory_order_relaxed);
    rank_boundary.latency_buckets[0].store(max_u64 / 2, std::memory_order_relaxed);
    rank_boundary.latency_buckets[1].store(max_u64, std::memory_order_relaxed);
    if (!Require(rank_boundary.ApproxP50Us() == 2,
            "FsHost p50 rank and cumulative count should be overflow-safe") ||
        !Require(rank_boundary.ApproxP95Us() == 2,
            "FsHost p95 rank and cumulative count should be overflow-safe"))
    {
        return false;
    }

    PerfCounter saturation{};
    saturation.count.store(max_u64, std::memory_order_relaxed);
    saturation.total_us.store(max_u64, std::memory_order_relaxed);
    saturation.latency_buckets[0].store(max_u64, std::memory_order_relaxed);
    saturation.Observe(1);
    if (!Require(saturation.count.load(std::memory_order_relaxed) == max_u64,
            "FsHost lifetime count should saturate") ||
        !Require(saturation.total_us.load(std::memory_order_relaxed) == max_u64,
            "FsHost lifetime total should saturate") ||
        !Require(saturation.latency_buckets[0].load(std::memory_order_relaxed) == max_u64,
            "FsHost histogram buckets should saturate"))
    {
        return false;
    }

    std::ostringstream json;
    AppendPerfCounterJson(json, "stage", counter);
    const auto serialized = json.str();
    return Require(
               serialized.find("\"p50Us\":1") != std::string::npos,
               "FsHost performance counters should expose the exact p50 latency") &&
           Require(
               serialized.find("\"p95Us\":4") != std::string::npos,
               "FsHost performance counters should expose the exact p95 latency") &&
           Require(
               serialized.find("\"stage\":{\"count\":4") != std::string::npos,
               "FsHost performance counters should preserve the stage counter name");
}

bool TestFsHostDispatcherThreadCountIsBoundedAndReported()
{
    SetEnvironmentVariableW(L"APFSACCESS_FSHOST_DISPATCHER_THREADS", nullptr);
    ScopeExit clear_dispatcher_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_FSHOST_DISPATCHER_THREADS", nullptr);
    }};

    if (!Require(ResolveDispatcherThreadCount() == 4, "FsHost dispatcher should use the bounded four-thread default"))
    {
        return false;
    }
    SetEnvironmentVariableW(L"APFSACCESS_FSHOST_DISPATCHER_THREADS", L"4");
    if (!Require(ResolveDispatcherThreadCount() == 4, "FsHost dispatcher should accept a bounded numeric override"))
    {
        return false;
    }
    SetEnvironmentVariableW(L"APFSACCESS_FSHOST_DISPATCHER_THREADS", L"64");
    if (!Require(ResolveDispatcherThreadCount() == 8, "FsHost dispatcher should cap excessive overrides"))
    {
        return false;
    }
    SetEnvironmentVariableW(L"APFSACCESS_FSHOST_DISPATCHER_THREADS", L"9x");
    if (!Require(ResolveDispatcherThreadCount() == 4, "FsHost dispatcher should validate the entire override before using the default"))
    {
        return false;
    }
    SetEnvironmentVariableW(L"APFSACCESS_FSHOST_DISPATCHER_THREADS", L"42949672960");
    if (!Require(ResolveDispatcherThreadCount() == 8, "FsHost dispatcher should safely clamp in-buffer numeric overflow"))
    {
        return false;
    }
    SetEnvironmentVariableW(L"APFSACCESS_FSHOST_DISPATCHER_THREADS", L"9999999999999999");
    if (!Require(ResolveDispatcherThreadCount() == 4, "FsHost dispatcher should reject overlength overrides with the default"))
    {
        return false;
    }
    SetEnvironmentVariableW(L"APFSACCESS_FSHOST_DISPATCHER_THREADS", L"invalid");
    if (!Require(ResolveDispatcherThreadCount() == 4, "FsHost dispatcher should reject non-numeric overrides with the default"))
    {
        return false;
    }

    SetEnvironmentVariableW(L"APFSACCESS_FSHOST_DISPATCHER_THREADS", L"4");
    g_dispatcher_start_file_system = nullptr;
    g_dispatcher_start_thread_count = 0;
    auto* const expected_file_system = reinterpret_cast<FSP_FILE_SYSTEM*>(static_cast<std::uintptr_t>(1));
    std::uint32_t resolved_thread_count = 0;
    if (!Require(
            NT_SUCCESS(StartDispatcherWithResolvedThreadCount(
                CaptureDispatcherStart,
                expected_file_system,
                resolved_thread_count)),
            "FsHost dispatcher wrapper should return the WinFsp Start status") ||
        !Require(g_dispatcher_start_file_system == expected_file_system,
            "FsHost dispatcher wrapper should preserve the file-system pointer") ||
        !Require(g_dispatcher_start_thread_count == 4 && resolved_thread_count == 4,
            "FsHost dispatcher wrapper should pass and report the resolved count"))
    {
        return false;
    }
    SetEnvironmentVariableW(L"APFSACCESS_FSHOST_DISPATCHER_THREADS", L"0");
    if (!Require(ResolveDispatcherThreadCount() == 4, "FsHost dispatcher should reject zero threads with the default"))
    {
        return false;
    }

    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"dispatcher-status-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (ec)
    {
        return Require(false, "Dispatcher status test should create its temp directory");
    }
    ScopeExit cleanup{[&]() { std::filesystem::remove_all(run_root, ec); }};

    MountContext context{};
    context.args.status_file = (run_root / "status.json").wstring();
    context.dispatcher_thread_count = 1;
    {
        ScopedCallbackActivity outer(&context, "telemetry-outer");
        ScopedCallbackActivity inner(&context, "telemetry-inner");
    }
    if (!Require(WriteHostStatusFile(context), "Dispatcher status file should be written"))
    {
        return false;
    }
    std::ifstream in(context.args.status_file, std::ios::binary);
    const std::string status_json{
        std::istreambuf_iterator<char>(in),
        std::istreambuf_iterator<char>()};
    return Require(
        status_json.find("\"dispatcherThreadCount\":1") != std::string::npos,
        "Host status should report the effective dispatcher count") &&
        Require(
            status_json.find("\"callbackDispatcherSaturationCount\":2") != std::string::npos,
            "Host status should report dispatcher saturation observations") &&
        Require(
            status_json.find("\"callbackQueueDepthPeakEstimate\":1") != std::string::npos,
            "Host status should report the estimated callback queue peak") &&
        Require(
            status_json.find("\"callbackQueueDepthEstimate\":0") != std::string::npos,
            "Host status should report an idle callback queue after callbacks return");
}

bool TestFsHostStatusSeparatesLockWaitCounters()
{
    SetEnvironmentVariableW(L"APFSACCESS_PERF_COUNTERS", L"1");
    ScopeExit clear_perf_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_PERF_COUNTERS", nullptr);
    }};

    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"lock-wait-status-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (ec)
    {
        return Require(false, "Lock-wait status test should create its temp directory");
    }
    ScopeExit cleanup{[&]() { std::filesystem::remove_all(run_root, ec); }};

    MountContext context{};
    context.args.status_file = (run_root / "status.json").wstring();
#ifdef APFSACCESS_HAS_RW_ENGINE
    context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{run_root / "spool", "lock-wait", 1024 * 1024});
    (void)context.payload_spool->CheckAppendCapacity(1);
#endif
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"LockWaitTelemetry");
    {
        std::unique_lock<std::mutex> held(context.tx_mutex);
        std::promise<void> worker_started;
        auto started = worker_started.get_future();
        auto worker = std::async(std::launch::async, [&]()
        {
            worker_started.set_value();
            return CommitMutationJournalBestEffort(&context);
        });
        started.wait();
        std::this_thread::sleep_for(std::chrono::milliseconds(20));
        held.unlock();
        if (!Require(worker.get(), "Observed transaction lock path should complete after contention"))
        {
            return false;
        }
    }

    ConfigureNativeCommitFailureForUnitTest(context);
    {
        std::unique_lock<std::mutex> held(context.commit_mutex);
        std::promise<void> worker_started;
        auto started = worker_started.get_future();
        auto worker = std::async(std::launch::async, [&]()
        {
            worker_started.set_value();
            return CommitNativeMutationsBestEffort(&context, L"TelemetryTest");
        });
        started.wait();
        std::this_thread::sleep_for(std::chrono::milliseconds(20));
        held.unlock();
        (void)worker.get();
    }
    if (!Require(context.perf_tx_mutex_wait.count.load(std::memory_order_relaxed) == 1,
            "Real transaction path should record one observed acquisition") ||
        !Require(context.perf_tx_mutex_wait.max_us.load(std::memory_order_relaxed) >= 10000,
            "Real transaction path should record concurrent contention") ||
        !Require(context.perf_commit_mutex_wait.count.load(std::memory_order_relaxed) == 1,
            "Real commit path should record one observed commit acquisition") ||
        !Require(context.perf_commit_mutex_wait.max_us.load(std::memory_order_relaxed) >= 10000,
            "Real commit path should record concurrent contention") ||
        !Require(context.perf_tx_mutex_hold.count.load(std::memory_order_relaxed) == 1,
            "Real transaction lock path should record one hold") ||
        !Require(context.perf_commit_mutex_hold.count.load(std::memory_order_relaxed) == 1,
            "Real commit lock path should record one hold") ||
        !Require(context.perf_metadata_mutex_wait.count.load(std::memory_order_relaxed) == 1,
            "Real commit path should record its observed metadata acquisition"))
    {
        return false;
    }
    if (!Require(WriteHostStatusFile(context), "Lock-wait status file should be written"))
    {
        return false;
    }

    std::ifstream in(context.args.status_file, std::ios::binary);
    const std::string status_json{
        std::istreambuf_iterator<char>(in),
        std::istreambuf_iterator<char>()};
    if (!Require(status_json.find("\"mutationAdmissionWait\"") != std::string::npos, "Status should expose mutation admission wait") ||
        !Require(status_json.find("\"selectedNativeWriteTxMutexWait\":{\"count\":1") != std::string::npos,
               "Status should expose the explicitly scoped transaction wait") ||
        !Require(status_json.find("\"selectedNativeWriteMetadataMutexWait\":{\"count\":1") != std::string::npos,
               "Status should expose the explicitly scoped metadata wait") ||
        !Require(status_json.find("\"selectedNativeCommitMutexWait\":{\"count\":1") != std::string::npos,
               "Status should expose the explicitly scoped commit wait") ||
        !Require(status_json.find("\"selectedNativeWriteTxMutexHold\":{\"count\":1") != std::string::npos,
               "Status should expose the explicitly scoped transaction hold") ||
        !Require(status_json.find("\"selectedNativeCommitMutexHold\":{\"count\":1") != std::string::npos,
               "Status should expose the explicitly scoped commit hold") ||
        !Require(status_json.find("\"payloadSpoolMutexWaitP50Microseconds\"") != std::string::npos,
               "Status should expose payload-spool mutex wait percentiles"))
    {
        return false;
    }

    SetEnvironmentVariableW(L"APFSACCESS_PERF_COUNTERS", L"0");
    context.args.status_file = (run_root / "status-disabled.json").wstring();
    if (!Require(WriteHostStatusFile(context), "Disabled-counter status file should be written"))
    {
        return false;
    }
    std::ifstream disabled_in(context.args.status_file, std::ios::binary);
    const std::string disabled_json{
        std::istreambuf_iterator<char>(disabled_in),
        std::istreambuf_iterator<char>()};
    SetEnvironmentVariableW(L"APFSACCESS_PERF_COUNTERS", L"1");
    std::mutex observed_mutex;
    PerfCounter observed_hold;
    {
        ObservedMutexGuard observed_lock(observed_mutex, nullptr, &observed_hold);
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }
    return Require(observed_hold.count.load(std::memory_order_relaxed) == 1,
               "Observed mutex helper should record a hold interval") &&
           Require(observed_hold.max_us.load(std::memory_order_relaxed) >= 5000,
               "Observed mutex helper should record the measurable hold interval") &&
           Require(disabled_json.find("\"performance\"") == std::string::npos,
               "Disabled status should omit the performance object") &&
           Require(disabled_json.find("payloadSpoolMutexWait") == std::string::npos,
               "Disabled status should omit payload-spool wait telemetry");
}

